  `Wert` varchar(255) DEFAULT NULL,
  `Authentizität` varchar(255) DEFAULT NULL,
  `Name_en` text DEFAULT NULL,
  `Beschreibung_en` text DEFAULT NULL,
  `abteilung_id` int(11) DEFAULT NULL,
  `normen` varchar(256) DEFAULT NULL COMMENT 'Kommagetrennte IDs verknüpfter Normen (aus Tabelle Normen)',
  `sync` tinyint(1) DEFAULT NULL,
  `synctime` datetime DEFAULT NULL,
  `Version` varchar(64) DEFAULT NULL,
  `vererbung_aus` tinyint(1) NOT NULL DEFAULT 0,
  `vererbung_grund` text DEFAULT NULL,
  `rto_stunden` int(11) DEFAULT NULL,
  `rpo_stunden` int(11) DEFAULT NULL,
  `maz_stunden` int(11) DEFAULT NULL,
  `bem_vertraulichkeit` text DEFAULT NULL,
  `bem_integritaet` text DEFAULT NULL,
  `bem_verfuegbarkeit` text DEFAULT NULL,
  `bem_authentizitaet` text DEFAULT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

