(54, '12. Business Continuity & Notfallmanagement', 'BCM-Tests und Notfallübungen werden mind. jährlich durchgeführt.', 1, 4, 'offen', NULL),
(55, '13. Compliance & Datenschutz', 'Relevante gesetzliche und regulatorische Anforderungen (DSGVO, HGB, etc.) sind identifiziert und eingehalten.', 1, 5, 'offen', NULL),
(56, '13. Compliance & Datenschutz', 'Interne Audits zur Informationssicherheit werden regelmäßig (mind. jährlich) durchgeführt.', 1, 5, 'offen', NULL),
(57, '13. Compliance & Datenschutz', 'Ein Datenschutzkonzept und ein Verzeichnis von Verarbeitungstätigkeiten (VVT) sind vorhanden.', 1, 4, 'offen', NULL),
(58, '13. Compliance & Datenschutz', 'Verstöße gegen Sicherheitsrichtlinien werden konsequent verfolgt und dokumentiert.', 0, 3, 'offen', NULL),
(59, '14. Patch- & Schwachstellenmanagement', 'Ein strukturierter Prozess zur zeitnahen Einspielung von Sicherheits-Patches ist etabliert.', 1, 5, 'offen', NULL),
(60, '14. Patch- & Schwachstellenmanagement', 'Schwachstellen in IT-Systemen werden regelmäßig gescannt und bewertet.', 1, 5, 'offen', NULL),
(61, '14. Patch- & Schwachstellenmanagement', 'Kritische Schwachstellen werden innerhalb definierter Fristen behoben.', 1, 5, 'offen', NULL),
(62, '14. Patch- & Schwachstellenmanagement', 'Software, die vom Hersteller nicht mehr unterstützt wird (End-of-Life), ist nicht produktiv im Einsatz.', 1, 5, 'offen', NULL);

-- --------------------------------------------------------

--
-- Tabellenstruktur für Tabelle `aud_abweichungen`
--

CREATE TABLE `aud_abweichungen` (
  `id` int(10) UNSIGNED NOT NULL,
  `audit_id` int(10) UNSIGNED NOT NULL,
  `nummer` varchar(20) DEFAULT NULL,
  `titel` varchar(200) NOT NULL,
  `beschreibung` text DEFAULT NULL,
  `typ` varchar(50) NOT NULL DEFAULT 'Empfehlung',
  `status` varchar(50) NOT NULL DEFAULT 'offen',
  `verantwortlich` int(10) UNSIGNED DEFAULT NULL,
  `faellig` date DEFAULT NULL,
  `norm` varchar(256) DEFAULT NULL,
  `norm_punkt` varchar(64) DEFAULT NULL,
  `massnahmen` text DEFAULT NULL,
  `Ersteller` int(10) UNSIGNED DEFAULT NULL,
  `erstellt` datetime NOT NULL DEFAULT current_timestamp(),
  `Aenderer` int(10) UNSIGNED DEFAULT NULL,
  `geaendert` datetime DEFAULT NULL,
  `ursachenanalyse` text DEFAULT NULL,
  `uebertragbarkeit` text DEFAULT NULL,
  `wirksamkeit` text DEFAULT NULL,
  `risiken` text DEFAULT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

-- --------------------------------------------------------

--
-- Tabellenstruktur für Tabelle `aud_anhaenge`
--

CREATE TABLE `aud_anhaenge` (
  `id` int(10) UNSIGNED NOT NULL,
  `audit_id` int(10) UNSIGNED NOT NULL,
  `original_name` varchar(255) NOT NULL,
  `stored_name` varchar(255) NOT NULL,
  `rel_path` varchar(255) NOT NULL,
  `mime_type` varchar(100) NOT NULL,
  `file_size` bigint(20) NOT NULL DEFAULT 0,
  `beschreibung` varchar(255) DEFAULT NULL,
  `ersteller` int(10) UNSIGNED DEFAULT NULL,
  `erstellt` date NOT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

-- --------------------------------------------------------

--
-- Tabellenstruktur für Tabelle `aud_audits`
--

CREATE TABLE `aud_audits` (
  `id` int(10) UNSIGNED NOT NULL,
  `nummer` varchar(20) DEFAULT NULL,
  `titel` varchar(200) NOT NULL,
  `beschreibung` text DEFAULT NULL,
  `datum_von` date DEFAULT NULL,
  `datum_bis` date DEFAULT NULL,
  `status` varchar(50) NOT NULL DEFAULT 'geplant',
  `art` varchar(20) NOT NULL DEFAULT 'intern',
  `auditor` varchar(200) DEFAULT NULL,
  `norm` varchar(256) DEFAULT NULL,
  `Ersteller` int(10) UNSIGNED DEFAULT NULL,
  `erstellt` datetime NOT NULL DEFAULT current_timestamp(),
  `Aenderer` int(10) UNSIGNED DEFAULT NULL,
  `geaendert` datetime DEFAULT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

-- --------------------------------------------------------

--
-- Tabellenstruktur für Tabelle `aud_gap_fortschritt`
--

CREATE TABLE `aud_gap_fortschritt` (
  `audit_id` int(10) UNSIGNED NOT NULL,
  `kapitel` char(40) NOT NULL COMMENT 'SHA-1 des Kapitelnamens',
  `status` varchar(16) NOT NULL DEFAULT 'begonnen' COMMENT 'begonnen | erledigt | uebersprungen',
  `position` int(10) UNSIGNED DEFAULT NULL COMMENT 'Pruefpunkt, bei dem es weitergeht',
  `benutzer` varchar(64) NOT NULL DEFAULT '',
  `geaendert` datetime DEFAULT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

-- --------------------------------------------------------

--
-- Tabellenstruktur für Tabelle `aud_pruefpunkte`
--

CREATE TABLE `aud_pruefpunkte` (
  `id` int(10) UNSIGNED NOT NULL,
  `audit_id` int(10) UNSIGNED NOT NULL,
  `norm_id` int(10) UNSIGNED DEFAULT NULL,
  `norm` varchar(256) DEFAULT NULL,
  `kapitel` varchar(256) DEFAULT NULL,
  `nummer` varchar(64) DEFAULT NULL,
  `titel` varchar(500) NOT NULL,
  `bewertung` varchar(32) NOT NULL DEFAULT 'offen',
  `feststellung` text DEFAULT NULL,
  `nachweis` text DEFAULT NULL,
  `abweichung_id` int(10) UNSIGNED DEFAULT NULL,
  `sortierung` int(11) NOT NULL DEFAULT 0,
  `Ersteller` int(10) UNSIGNED DEFAULT NULL,
  `erstellt` datetime NOT NULL DEFAULT current_timestamp(),
  `Aenderer` int(10) UNSIGNED DEFAULT NULL,
  `geaendert` datetime DEFAULT NULL,
  `beschreibung` text DEFAULT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

--
-- Daten für Tabelle `aud_pruefpunkte`
--

INSERT INTO `aud_pruefpunkte` (`id`, `audit_id`, `norm_id`, `norm`, `kapitel`, `nummer`, `titel`, `bewertung`, `feststellung`, `nachweis`, `abweichung_id`, `sortierung`, `Ersteller`, `erstellt`, `Aenderer`, `geaendert`, `beschreibung`) VALUES
(26, 2, 560, 'ISO/IEC 27001:2022', 'Anhang A', 'A.5.4', 'Leitungsverantwortung', 'offen', NULL, NULL, NULL, 560, 18, '2026-08-30 17:52:17', 18, '2026-09-22 11:38:29', 'Wie zeigt die Geschäftsführung konkret ihre Unterstützung für Informationssicherheit, z. B. durch Budgetfreigabe, Teilnahme an Reviews oder Vorbildfunktion?\nWelche Ressourcen – Zeit, Budget, Werkzeuge – stehen für das ISMS zur Verfügung?\nWie wird die Leitungsunterstützung dokumentiert, z. B. Protokolle der Managementbewertung, freigegebene Richtlinien oder Investitionsentscheidungen?'),
(27, 2, 561, 'ISO/IEC 27001:2022', 'Anhang A', 'A.5.5', 'Kontakt zu Behörden', 'offen', NULL, NULL, NULL, 561, 18, '2026-08-30 17:52:17', 18, '2026-09-22 11:38:29', 'Welche Behörden sind für Ihre IT/Software-GmbH sicherheitsrelevant, z. B. BSI, Datenschutzaufsicht Baden-Württemberg oder CERT-Bund?\nWie haben Sie die Kontaktdaten dieser Stellen dokumentiert und wer ist intern für die Kontaktaufnahme zuständig?\nIn welchen Fällen würden Sie Behörden kontaktieren, z. B. bei meldepflichtigen Datenschutzvorfällen oder Cyberangriffen?\nWelche Nachweise gibt es, z. B. eine Kontaktliste oder ein Notfallhandbuch?'),
(28, 2, 562, 'ISO/IEC 27001:2022', 'Anhang A', 'A.5.6', 'Kontakt zu Interessengruppen', 'offen', NULL, NULL, NULL, 562, 18, '2026-08-30 17:52:17', 18, '2026-09-22 11:38:29', 'Mit welchen externen Interessengruppen tauschen Sie sich zur Informationssicherheit aus, z. B. Branchenverbänden, CERT-Netzwerken oder Kundengruppen?\nWie ist dieser Austausch organisiert und dokumentiert?\nWelchen Nutzen ziehen Sie aus diesen Kontakten für Ihr ISMS und Ihre Softwareentwicklung?\nWer ist intern für die Pflege dieser Beziehungen verantwortlich?'),
(29, 2, 563, 'ISO/IEC 27001:2022', 'Anhang A', 'A.5.7', 'Threat Intelligence', 'offen', NULL, NULL, NULL, 563, 18, '2026-08-30 17:52:17', 18, '2026-09-22 11:38:29', 'Wie informieren Sie sich über aktuelle Bedrohungen und Angriffsmethoden, die für Ihre Softwareentwicklung und Ihren SaaS-Betrieb relevant sind?\nWelche Quellen nutzen Sie, z. B. BSI-Warnmeldungen, CVE-Datenbanken, Fachportale oder Herstellerinformationen?\nWie fließen diese Erkenntnisse in konkrete Schutzmaßnahmen oder Entwicklungsentscheidungen ein?\nWelche Nachweise dokumentieren die Auswertung, z. B. protokollierte Bewertungen oder Maßnahmenableitung?'),
(30, 2, 564, 'ISO/IEC 27001:2022', 'Anhang A', 'A.5.8', 'Informationssicherheit im Projektmanagement', 'offen', NULL, NULL, NULL, 564, 18, '2026-08-30 17:52:17', 18, '2026-09-22 11:38:29', 'Wie stellen Sie sicher, dass Sicherheitsanforderungen von Anfang an in Ihre Softwareprojekte einfließen – von der Planung bis zur Produktivsetzung?\nWelche Sicherheitsaspekte prüfen Sie bei neuen Features oder Releases, z. B. sichere Architektur, Authentifizierung oder Datenverschlüsselung?\nWie dokumentieren Sie sicherheitsrelevante Entscheidungen in Projekten, z. B. in Projektplänen, User Stories oder Abnahmeprotokollen?\nWer trägt die Verantwortung für Informationssicherheit in Projekten?'),
(31, 2, 565, 'ISO/IEC 27001:2022', 'Anhang A', 'A.5.9', 'Asset-Inventar', 'offen', NULL, NULL, NULL, 565, 18, '2026-08-30 17:52:17', 18, '2026-09-22 11:38:29', 'Führen Sie ein Verzeichnis Ihrer Informationswerte, z. B. Kundendaten, Quellcode, Server, Entwicklungsumgebungen oder SaaS-Infrastruktur?\nWie dokumentieren Sie Zuständigkeiten und Schutzbedarf je Asset?\nWie halten Sie das Inventar aktuell, etwa bei neuen Systemen oder Änderungen?\nWelche Nachweise gibt es, z. B. eine Asset-Liste, CMDB oder Tabelle mit Verantwortlichen und Klassifizierung?'),
(32, 2, 566, 'ISO/IEC 27001:2022', 'Anhang A', 'A.5.10', 'Erlaubte Nutzung von Assets', 'offen', NULL, NULL, NULL, 566, 18, '2026-08-30 17:52:17', 18, '2026-09-22 11:38:29', 'Welche Regeln gelten für die Nutzung von Arbeitsmitteln und Informationswerten, z. B. Laptops, Cloud-Dienste oder Quellcode-Repositories?\nWie verhindern Sie Missbrauch oder unbeabsichtigten Datenabfluss, etwa durch private Nutzung oder unsichere Tools?\nWie sind diese Regeln dokumentiert und kommuniziert, z. B. in einer Nutzungsrichtlinie oder Arbeitsanweisung?\nWie kontrollieren Sie die Einhaltung in Ihrem kleinen Team?'),
(33, 2, 567, 'ISO/IEC 27001:2022', 'Anhang A', 'A.5.11', 'Rückgabe von Assets', 'offen', NULL, NULL, NULL, 567, 18, '2026-08-30 17:52:17', 18, '2026-09-22 11:38:29', 'Wie stellen Sie sicher, dass bei Austritt, Rollenwechsel oder Vertragsende alle Assets und Zugänge zurückgegeben bzw. entzogen werden?\nWelcher Prozess wird durchlaufen, z. B. Checkliste, Offboarding-Protokoll oder Übergabegespräch?\nWie dokumentieren Sie die Rückgabe, z. B. durch Unterschrift, Ticketnachweis oder Systemprotokoll?\nWie schnell werden Zugänge nach Austritt gesperrt?'),
(34, 2, 568, 'ISO/IEC 27001:2022', 'Anhang A', 'A.5.12', 'Klassifizierung von Informationen', 'offen', NULL, NULL, NULL, 568, 18, '2026-08-30 17:52:17', 18, '2026-09-22 11:38:29', 'Nach welchem Schema klassifizieren Sie Informationen hinsichtlich Vertraulichkeit, Integrität und Verfügbarkeit?\nWelche Klassifizierungsstufen nutzen Sie und wie sind diese definiert?\nWie leiten Sie aus der Klassifizierung konkrete Schutzmaßnahmen ab, z. B. Verschlüsselung, Zugriffsbeschränkung oder Backup-Anforderungen?\nWelche Dokumente belegen das Klassifizierungsschema, z. B. eine Richtlinie oder eine Übersicht je Informationsart?'),
(35, 2, 569, 'ISO/IEC 27001:2022', 'Anhang A', 'A.5.13', 'Kennzeichnung von Informationen', 'offen', NULL, NULL, NULL, 569, 18, '2026-08-30 17:52:17', 18, '2026-09-22 11:38:29', 'Wie kennzeichnen Sie klassifizierte Informationen, damit der Schutzbedarf im Alltag erkennbar ist – etwa in Dokumenten, E-Mails oder Dateien?\nWelche Kennzeichnungsarten nutzen Sie, z. B. Wasserzeichen, Kopfzeilen, Ordnerstruktur oder Metadaten?\nWie stellen Sie sicher, dass alle Mitarbeiter die Kennzeichnung verstehen und anwenden?\nWelche Nachweise gibt es, z. B. eine Kennzeichnungsrichtlinie oder Beispieldokumente?'),
(36, 2, 570, 'ISO/IEC 27001:2022', 'Anhang A', 'A.5.14', 'Informationsübertragung', 'offen', NULL, NULL, NULL, 570, 18, '2026-08-30 17:52:17', 18, '2026-09-22 11:38:29', 'Wie regeln Sie den sicheren Austausch von Informationen – intern und mit Kunden oder Partnern?\nWelche Kanäle sind für welche Vertraulichkeitsstufe erlaubt, z. B. verschlüsselte E-Mail, SFTP, sichere Cloud oder Kundenportal?\nWie dokumentieren Sie Freigaben und Schutzmaßnahmen für Übertragungen, z. B. in einer Richtlinie oder Transferprotokoll?\nWie gehen Sie mit dem Versand sensibler Daten an Ihre SaaS-Kunden um?'),
(37, 2, 571, 'ISO/IEC 27001:2022', 'Anhang A', 'A.5.15', 'Zugriffskontrolle', 'offen', NULL, NULL, NULL, 571, 18, '2026-08-30 17:52:17', 18, '2026-09-22 11:38:29', 'Wie stellen Sie sicher, dass Zugriffsrechte nur nach dem Need-to-know- und Least-Privilege-Prinzip vergeben werden?\nWie überwachen und protokollieren Sie Zugriffe auf kritische Systeme, z. B. Quellcode-Repositories, Produktionsumgebung oder Kundendaten?\nIn welchem Turnus überprüfen Sie bestehende Berechtigungen?\nWelche Nachweise dokumentieren die Zugriffskontrolle, z. B. Berechtigungsmatrix, Audit-Logs oder Rezertifizierungsprotokolle?'),
(38, 2, 572, 'ISO/IEC 27001:2022', 'Anhang A', 'A.5.16', 'Identitätsmanagement', 'offen', NULL, NULL, NULL, 572, 18, '2026-08-30 17:52:17', 18, '2026-09-22 11:38:29', 'Wie verwalten Sie Identitäten über ihren gesamten Lebenszyklus – Anlage, Änderung und Deaktivierung?\nWelche Systeme nutzen Sie für das Identitätsmanagement, z. B. Active Directory, Identity Provider oder manuelle Pflege?\nWie stellen Sie Nachvollziehbarkeit sicher, z. B. durch Protokollierung oder Tickethistorie?\nWie schnell werden Identitäten bei Austritt oder Rollenwechsel angepasst?'),
(39, 2, 573, 'ISO/IEC 27001:2022', 'Anhang A', 'A.5.17', 'Authentifizierungsinformationen', 'offen', NULL, NULL, NULL, 573, 18, '2026-08-30 17:52:17', 18, '2026-09-22 11:38:29', 'Wie stellen Sie sicher, dass Passwörter und andere Authentifizierungsdaten sicher erstellt, gespeichert und übertragen werden?\nWelche Vorgaben gibt es für Passwortkomplexität, Ablauf und Mehrfaktorauthentifizierung?\nWie schützen Sie Authentifizierungsdaten technisch, z. B. durch Passwort-Manager, Hashing oder sichere Übertragung?\nWelche Nachweise dokumentieren Ihre Vorgaben, z. B. eine Passwortrichtlinie oder Systemkonfiguration?'),
(40, 2, 574, 'ISO/IEC 27001:2022', 'Anhang A', 'A.5.18', 'Berechtigungsverwaltung', 'offen', NULL, NULL, NULL, 574, 18, '2026-08-30 17:52:17', 18, '2026-09-22 11:38:29', 'Wie werden Zugriffsrechte vergeben und dokumentiert – wer beantragt, wer genehmigt?\nIn welchem Turnus überprüfen Sie bestehende Berechtigungen auf Aktualität und Angemessenheit (Rezertifizierung)?\nWie schnell werden Rechte entzogen, wenn sie nicht mehr benötigt werden, z. B. nach Projektwechsel oder Kündigung?\nWelche Nachweise gibt es, z. B. Antragsformulare, Genehmigungsprotokolle oder Rezertifizierungslisten?'),
(41, 2, 575, 'ISO/IEC 27001:2022', 'Anhang A', 'A.5.19', 'Informationssicherheit bei Lieferanten', 'offen', NULL, NULL, NULL, 575, 18, '2026-08-30 17:52:17', 18, '2026-09-22 11:39:18', 'Welche Lieferanten sind für Ihre ISMS-Software und den SaaS-Betrieb besonders kritisch, z. B. Hosting-Provider, Entwicklungstools oder Drittkomponenten?\nWie bewerten Sie neue und bestehende Lieferanten hinsichtlich Informationssicherheitsrisiken, z. B. mittels Checkliste, Fragebogen oder Zertifikatsprüfung?\nWelche Kriterien legen Sie an, um die Kritikalität eines Lieferanten für Ihren Geltungsbereich einzustufen?\nWie dokumentieren Sie die Ergebnisse Ihrer Lieferantenbewertung, z. B. in einer Lieferantenliste oder einem Bewertungsprotokoll?'),
(42, 2, 576, 'ISO/IEC 27001:2022', 'Anhang A', 'A.5.20', 'Sicherheitsanforderungen an Lieferanten', 'offen', NULL, NULL, NULL, 576, 18, '2026-08-30 17:52:17', 18, '2026-09-22 11:39:18', 'Wie stellen Sie sicher, dass Sicherheitsanforderungen in Verträgen mit Lieferanten verankert sind, z. B. durch Vertragszusätze, AVV oder NDA?\nWelche konkreten Sicherheitsklauseln vereinbaren Sie typischerweise mit Ihren Hosting- oder Cloud-Anbietern?\nWie passen Sie die vertraglichen Anforderungen an den jeweiligen Schutzbedarf und das Risiko an?\nWo sind diese Vertragsvorlagen oder -muster abgelegt und wer prüft deren Einhaltung bei Vertragsabschluss?'),
(43, 2, 577, 'ISO/IEC 27001:2022', 'Anhang A', 'A.5.21', 'Lieferantenüberwachung', 'offen', NULL, NULL, NULL, 577, 18, '2026-08-30 17:52:17', 18, '2026-09-22 11:39:18', 'Wie überwachen Sie, ob Ihre kritischen Lieferanten die vereinbarten Sicherheitsanforderungen einhalten, z. B. durch Zertifikatsnachfrage, Auditberichte oder regelmäßige Selbstauskünfte?\nIn welchem Turnus fordern Sie Nachweise wie ISO-27001-Zertifikate oder SOC-2-Berichte von Ihren Cloud-Anbietern an?\nWie gehen Sie vor, wenn ein Lieferant die vereinbarten Anforderungen nicht mehr erfüllt?\nWelche Aufzeichnungen führen Sie über die Lieferantenüberwachung?'),
(44, 2, 578, 'ISO/IEC 27001:2022', 'Anhang A', 'A.5.22', 'Service-Delivery-Management', 'offen', NULL, NULL, NULL, 578, 18, '2026-08-30 17:52:17', 18, '2026-09-22 11:39:18', 'Welche Dienstleistungen haben Sie ausgelagert, z. B. Hosting, Backup, Support oder Softwareentwicklung?\nWie steuern Sie im laufenden Betrieb, dass diese Dienstleister Ihre Sicherheitsanforderungen einhalten, z. B. durch SLAs, regelmäßige Abstimmungen oder Incident-Meldepflichten?\nWer ist intern verantwortlich für die Überwachung ausgelagerter Leistungen?\nWie dokumentieren Sie Abweichungen oder Sicherheitsvorfälle beim Dienstleister?'),
(45, 2, 579, 'ISO/IEC 27001:2022', 'Anhang A', 'A.5.23', 'Nutzung von Cloud-Diensten', 'offen', NULL, NULL, NULL, 579, 18, '2026-08-30 17:52:17', 18, '2026-09-22 11:39:18', 'Welche Cloud-Dienste nutzen Sie für Ihre ISMS-Software und den internen Betrieb, z. B. IaaS, PaaS oder SaaS-Lösungen?\nWie haben Sie vor Nutzung eines Cloud-Dienstes die Risiken bewertet und dokumentiert?\nWelche Sicherheitskontrollen setzen Sie für Cloud-Dienste um, z. B. Verschlüsselung, Zugriffsmanagement oder Standortwahl?\nWie stellen Sie sicher, dass Cloud-Anbieter die Anforderungen der DSGVO und ggf. NIS2 erfüllen?'),
(46, 2, 580, 'ISO/IEC 27001:2022', 'Anhang A', 'A.5.24', 'Incident-Management', 'offen', NULL, NULL, NULL, 580, 18, '2026-08-30 17:52:17', 18, '2026-09-22 11:39:18', 'Wie erkennen Sie Sicherheitsvorfälle in Ihrem Unternehmen, z. B. durch Monitoring, Meldungen oder automatisierte Alarme?\nWer ist für die Entgegennahme und Erstbewertung von Vorfällen zuständig und wie erreicht man diese Person?\nWie dokumentieren Sie Sicherheitsvorfälle von der Meldung bis zur Lösung, z. B. in einem Ticketsystem oder Vorfallsprotokoll?\nWelche Kriterien nutzen Sie, um einen Vorfall als sicherheitsrelevant einzustufen?'),
(47, 2, 581, 'ISO/IEC 27001:2022', 'Anhang A', 'A.5.25', 'Bewertung von Sicherheitsereignissen', 'offen', NULL, NULL, NULL, 581, 18, '2026-08-30 17:52:17', 18, '2026-09-22 11:39:18', 'Wie unterscheiden Sie zwischen einem Sicherheitsereignis und einem echten Sicherheitsvorfall?\nNach welchen Kriterien priorisieren Sie Sicherheitsereignisse, z. B. Auswirkung, Dringlichkeit oder betroffene Assets?\nWie stellen Sie sicher, dass relevante Ereignisse zeitnah analysiert und in den Reaktionsprozess überführt werden?\nWelche Aufzeichnungen gibt es zur Analyse und Priorisierung von Ereignissen?'),
(48, 2, 582, 'ISO/IEC 27001:2022', 'Anhang A', 'A.5.26', 'Reaktion auf Sicherheitsvorfälle', 'offen', NULL, NULL, NULL, 582, 18, '2026-08-30 17:52:17', 18, '2026-09-22 11:39:18', 'Welche Abläufe haben Sie definiert, um Sicherheitsvorfälle einzudämmen und zu beheben, z. B. in einem Incident-Response-Plan oder Notfallhandbuch?\nWie stellen Sie die Wiederherstellung betroffener Systeme oder Daten nach einem Vorfall sicher?\nWer kommuniziert intern und extern bei einem Vorfall und nach welchen Vorgaben?\nKönnen Sie ein Beispiel nennen, wie Sie zuletzt auf einen Vorfall reagiert haben?'),
(49, 2, 583, 'ISO/IEC 27001:2022', 'Anhang A', 'A.5.27', 'Lernen aus Vorfällen', 'offen', NULL, NULL, NULL, 583, 18, '2026-08-30 17:52:17', 18, '2026-09-22 11:39:18', 'Wie werten Sie abgeschlossene Sicherheitsvorfälle aus, um Ursachen zu identifizieren und Wiederholungen zu vermeiden?\nWelche Maßnahmen haben Sie aus früheren Vorfällen abgeleitet und umgesetzt?\nWie dokumentieren Sie die Lessons Learned und wo werden diese festgehalten, z. B. in einem Vorfallsbericht oder Maßnahmenplan?\nWer ist verantwortlich für die Nachverfolgung und Umsetzung von Verbesserungen?'),
(50, 2, 584, 'ISO/IEC 27001:2022', 'Anhang A', 'A.5.28', 'Beweissicherung', 'offen', NULL, NULL, NULL, 584, 18, '2026-08-30 17:52:17', 18, '2026-09-22 11:39:18', 'Wie sichern Sie bei einem Sicherheitsvorfall Beweise, z. B. Logdateien, Screenshots oder E-Mails?\nWie stellen Sie sicher, dass gesicherte Belege nicht verändert werden können und nachvollziehbar bleiben?\nWelche Vorgaben haben Sie für die Beweissicherung, damit diese im Streitfall rechtlich verwertbar ist?\nWo und wie lange bewahren Sie solche Belege auf?'),
(51, 2, 585, 'ISO/IEC 27001:2022', 'Anhang A', 'A.5.29', 'Informationssicherheit in Notfällen', 'offen', NULL, NULL, NULL, 585, 18, '2026-08-30 17:52:17', 18, '2026-09-22 11:39:18', 'Haben Sie Notfall- oder Krisenpläne, die Informationssicherheit explizit berücksichtigen?\nWie stellen Sie sicher, dass auch im Notfallbetrieb Vertraulichkeit, Integrität und Verfügbarkeit Ihrer Daten gewahrt bleiben?\nWelche Szenarien haben Sie für Ihre ISMS-Software und den SaaS-Betrieb durchgespielt?\nWie sind Verantwortlichkeiten und Kommunikationswege im Notfall geregelt?'),
(52, 2, 586, 'ISO/IEC 27001:2022', 'Anhang A', 'A.5.30', 'IKT-Bereitschaft für Business Continuity', 'offen', NULL, NULL, NULL, 586, 18, '2026-08-30 17:52:17', 18, '2026-09-22 11:39:18', 'Welche IT-Systeme und Prozesse sind für den Betrieb Ihrer ISMS-Software und die Kundenbetreuung kritisch?\nWie haben Sie die Wiederherstellungszeiten und -ziele für diese Systeme definiert, z. B. RTO und RPO?\nWelche Maßnahmen haben Sie getroffen, um den Betrieb bei Ausfall kritischer Systeme fortzuführen, z. B. Backups, Redundanzen oder Notfallzugänge?\nWie testen Sie Ihre Business-Continuity-Maßnahmen, z. B. durch Wiederherstellungstests?'),
(53, 2, 587, 'ISO/IEC 27001:2022', 'Anhang A', 'A.5.31', 'Rechtliche Anforderungen', 'offen', NULL, NULL, NULL, 587, 18, '2026-08-30 17:52:17', 18, '2026-09-22 11:39:18', 'Wie ermitteln Sie, welche gesetzlichen, regulatorischen und vertraglichen Anforderungen für Ihre ISMS-Software und Beratung gelten, z. B. DSGVO, NIS2 oder Kundenverträge?\nWo dokumentieren Sie diese Anforderungen und wie halten Sie diese aktuell?\nWie stellen Sie die Umsetzung dieser Pflichten im Tagesgeschäft sicher?\nWer ist für die Überwachung und Aktualisierung rechtlicher Anforderungen verantwortlich?'),
(54, 2, 588, 'ISO/IEC 27001:2022', 'Anhang A', 'A.5.32', 'Geistiges Eigentum', 'offen', NULL, NULL, NULL, 588, 18, '2026-08-30 17:52:17', 18, '2026-09-22 11:39:18', 'Wie schützen Sie Ihr Know-how und Ihren Quellcode vor unbefugtem Zugriff oder Weitergabe?\nWie stellen Sie sicher, dass eingesetzte Software und Bibliotheken lizenzkonform genutzt werden, z. B. durch ein Lizenzregister oder regelmäßige Prüfungen?\nWelche Regelungen haben Sie für Mitarbeitende und Dritte zum Umgang mit geistigem Eigentum, z. B. in Arbeitsverträgen oder NDAs?\nWie dokumentieren Sie Ihre eigenen Schutzrechte?'),
(55, 2, 589, 'ISO/IEC 27001:2022', 'Anhang A', 'A.5.33', 'Schutz von Aufzeichnungen', 'offen', NULL, NULL, NULL, 589, 18, '2026-08-30 17:52:17', 18, '2026-09-22 11:39:18', 'Welche Aufzeichnungen führen Sie für Ihr ISMS und den laufenden Betrieb, z. B. Protokolle, Verträge oder Nachweise?\nWie stellen Sie sicher, dass diese Aufzeichnungen vor unbefugter Änderung oder Verlust geschützt sind?\nNach welchen Kriterien legen Sie Aufbewahrungsfristen fest und wie stellen Sie die fristgerechte Löschung sicher?\nWo sind Ihre Aufzeichnungen abgelegt und wer hat Zugriff?'),
(56, 2, 590, 'ISO/IEC 27001:2022', 'Anhang A', 'A.5.34', 'Datenschutz', 'offen', NULL, NULL, NULL, 590, 18, '2026-08-30 17:52:17', 18, '2026-09-22 11:39:18', 'Welche personenbezogenen Daten verarbeiten Sie im Rahmen Ihrer ISMS-Software und Beratung?\nWelche technischen und organisatorischen Maßnahmen setzen Sie zum Schutz dieser Daten um, z. B. Verschlüsselung, Zugriffskontrollen oder Pseudonymisierung?\nWie arbeiten Sie mit Ihrem Datenschutzbeauftragten oder einer externen Datenschutzberatung zusammen?\nWie dokumentieren Sie Ihre Datenschutzmaßnahmen, z. B. im Verzeichnis von Verarbeitungstätigkeiten?'),
(57, 2, 591, 'ISO/IEC 27001:2022', 'Anhang A', 'A.5.35', 'Unabhängige Sicherheitsprüfung', 'offen', NULL, NULL, NULL, 591, 18, '2026-08-30 17:52:17', 18, '2026-09-22 11:39:18', 'Wie und in welchem Turnus lassen Sie Ihre Sicherheitsmaßnahmen unabhängig prüfen, z. B. durch externe Audits, Penetrationstests oder Zertifizierungen?\nWer führt diese Prüfungen durch und wie wählen Sie geeignete Prüfer aus?\nWie gehen Sie mit den Ergebnissen und Empfehlungen aus solchen Prüfungen um?\nWelche Nachweise über durchgeführte Prüfungen liegen vor, z. B. Auditberichte oder Testprotokolle?'),
(58, 2, 592, 'ISO/IEC 27001:2022', 'Anhang A', 'A.5.36', 'Einhaltung von Richtlinien', 'offen', NULL, NULL, NULL, 592, 18, '2026-08-30 17:52:17', 18, '2026-09-22 11:39:18', 'Wie überprüfen Sie, ob Ihre internen Sicherheitsrichtlinien im Alltag eingehalten werden, z. B. durch Stichproben, Self-Assessments oder Reviews?\nWie gehen Sie vor, wenn Sie Abweichungen von Ihren Vorgaben feststellen?\nWer ist für die Überwachung der Richtlinieneinhaltung verantwortlich?\nWelche Aufzeichnungen führen Sie über Compliance-Prüfungen und eingeleitete Maßnahmen?'),
(59, 2, 593, 'ISO/IEC 27001:2022', 'Anhang A', 'A.5.37', 'Technische Compliance', 'offen', NULL, NULL, NULL, 593, 18, '2026-08-30 17:52:17', 18, '2026-09-22 11:39:18', 'Welche technischen Vorgaben und Baselines haben Sie für Ihre IT-Systeme definiert, z. B. Härtungsvorgaben, Patchstände oder Konfigurationsstandards?\nWie kontrollieren Sie regelmäßig, ob diese technischen Vorgaben eingehalten werden, z. B. durch Scans, automatisierte Prüfungen oder Reviews?\nWie dokumentieren Sie Abweichungen und deren Behebung?\nWer ist für die technische Compliance verantwortlich?'),
(60, 2, 594, 'ISO/IEC 27001:2022', 'Anhang A', 'A.6.1', 'Hintergrundprüfungen', 'offen', NULL, NULL, NULL, 594, 18, '2026-08-30 17:52:17', 18, '2026-09-22 11:39:18', 'Welche Hintergrundprüfungen führen Sie vor der Einstellung neuer Mitarbeitender durch, z. B. Referenzprüfung, Identitätsprüfung oder Führungszeugnis?\nWie stellen Sie sicher, dass diese Prüfungen im rechtlich zulässigen Rahmen erfolgen, z. B. unter Beachtung des BDSG?\nFühren Sie auch während der Beschäftigung anlassbezogene Prüfungen durch?\nWie dokumentieren Sie die durchgeführten Prüfungen, z. B. in der Personalakte?'),
(61, 2, 595, 'ISO/IEC 27001:2022', 'Anhang A', 'A.6.2', 'Arbeitsverträge', 'offen', NULL, NULL, NULL, 595, 18, '2026-08-30 17:52:17', 18, '2026-09-22 11:40:04', 'Welche Sicherheitsanforderungen und Vertraulichkeitspflichten sind in Ihren Arbeitsverträgen verankert?\nWie stellen Sie sicher, dass neue Mitarbeitende vor Arbeitsbeginn eine Verpflichtungserklärung zur Informationssicherheit unterzeichnen, z. B. NDA oder Datenschutzverpflichtung?\nWelche Dokumente belegen die vertragliche Verankerung, z. B. Musterarbeitsvertrag, Zusatzvereinbarungen, unterschriebene Verpflichtungserklärungen?\nWer prüft, ob die vertraglichen Sicherheitsklauseln bei Vertragsänderungen oder Rollenwechseln aktualisiert werden?'),
(62, 2, 596, 'ISO/IEC 27001:2022', 'Anhang A', 'A.6.3', 'Sensibilisierung und Schulung', 'offen', NULL, NULL, NULL, 596, 18, '2026-08-30 17:52:17', 18, '2026-09-22 11:40:04', 'Wie werden Ihre Mitarbeitenden regelmäßig zu Informationssicherheitsrisiken und ISMS-Vorgaben geschult?\nIn welchen Intervallen finden Sensibilisierungsmaßnahmen statt und wer ist für deren Durchführung verantwortlich?\nWelche Nachweise dokumentieren die Teilnahme, z. B. Teilnehmerlisten, E-Learning-Zertifikate, Protokolle?\nWie passen Sie Schulungsinhalte an aktuelle Bedrohungen an, etwa Phishing oder Social Engineering im Softwareentwicklungsumfeld?'),
(63, 2, 597, 'ISO/IEC 27001:2022', 'Anhang A', 'A.6.4', 'Disziplinarische Maßnahmen', 'offen', NULL, NULL, NULL, 597, 18, '2026-08-30 17:52:17', 18, '2026-09-22 11:40:04', 'Gibt es in Ihrem Unternehmen definierte Konsequenzen bei Verstößen gegen Sicherheitsregeln?\nWie sind diese Maßnahmen abgestuft und wo sind sie dokumentiert, z. B. in einer Richtlinie, Betriebsvereinbarung oder im Arbeitsvertrag?\nWie stellen Sie sicher, dass alle Mitarbeitenden diese Konsequenzen kennen?\nWer entscheidet über disziplinarische Maßnahmen und wie wird die Verhältnismäßigkeit gewahrt?'),
(64, 2, 598, 'ISO/IEC 27001:2022', 'Anhang A', 'A.6.5', 'Verantwortlichkeiten nach Beendigung', 'offen', NULL, NULL, NULL, 598, 18, '2026-08-30 17:52:17', 18, '2026-09-22 11:40:04', 'Welche Pflichten zur Vertraulichkeit und zum Schutz von Informationen gelten für ausscheidende Mitarbeitende über das Beschäftigungsende hinaus?\nWie werden diese Pflichten vertraglich festgehalten, z. B. in Aufhebungsverträgen, nachvertraglichen Klauseln oder separaten NDAs?\nWie erinnern Sie ausscheidende Mitarbeitende an fortbestehende Pflichten, etwa durch ein Exit-Gespräch oder Checkliste?\nWelche Nachweise existieren, z. B. unterschriebene Austrittsdokumente?'),
(65, 2, 599, 'ISO/IEC 27001:2022', 'Anhang A', 'A.6.6', 'Vertraulichkeitsvereinbarungen', 'offen', NULL, NULL, NULL, 599, 18, '2026-08-30 17:52:17', 18, '2026-09-22 11:40:04', 'Für welche Rollen und externen Partner bestehen Vertraulichkeitsvereinbarungen?\nWie stellen Sie sicher, dass NDAs vor Zugang zu sensiblen Informationen unterzeichnet werden?\nWelche Dokumente belegen dies, z. B. unterschriebene NDAs, Rahmenverträge mit Vertraulichkeitsklauseln?\nWer verwaltet diese Vereinbarungen und prüft deren Aktualität bei langjährigen Partnern?'),
(66, 2, 600, 'ISO/IEC 27001:2022', 'Anhang A', 'A.6.7', 'Remote Work', 'offen', NULL, NULL, NULL, 600, 18, '2026-08-30 17:52:17', 18, '2026-09-22 11:40:04', 'Welche Regeln gelten für Remote Work und Homeoffice hinsichtlich Gerätenutzung, Netzwerksicherheit und Zugriffsschutz?\nWo sind diese Vorgaben dokumentiert, z. B. in einer Remote-Work-Richtlinie oder IT-Nutzungsordnung?\nWie schützen Ihre Mitarbeitenden sensible Informationen bei mobilem Arbeiten, etwa durch VPN, Bildschirmschutzfolien oder verschlüsselte Geräte?\nWie überprüfen Sie die Einhaltung dieser Regeln?'),
(67, 2, 601, 'ISO/IEC 27001:2022', 'Anhang A', 'A.6.8', 'Meldung von Sicherheitsereignissen', 'offen', NULL, NULL, NULL, 601, 18, '2026-08-30 17:52:17', 18, '2026-09-22 11:40:04', 'Über welche Kanäle melden Ihre Mitarbeitenden Sicherheitsvorfälle oder Auffälligkeiten?\nWie ist der Meldeprozess dokumentiert und allen bekannt gemacht, z. B. durch Aushang, Intranet oder Schulung?\nWelche Nachweise gibt es für eingegangene Meldungen, z. B. Ticketsystem, E-Mail-Postfach, Meldeprotokoll?\nWie schnell erfolgt typischerweise die Erstreaktion auf eine Meldung?'),
(68, 2, 602, 'ISO/IEC 27001:2022', 'Anhang A', 'A.7.1', 'Sicherheitszonen', 'offen', NULL, NULL, NULL, 602, 18, '2026-08-30 17:52:17', 18, '2026-09-22 11:40:04', 'Wie haben Sie Bereiche mit unterschiedlichem Schutzbedarf in Ihren Räumlichkeiten definiert?\nWelche Zutrittsmaßnahmen schützen sensible Bereiche wie Serverraum oder Entwicklungsarbeitsplätze?\nWo ist die Zonenklassifizierung dokumentiert, z. B. in einem Raumplan oder Sicherheitskonzept?\nWie berücksichtigen Sie den Schutzbedarf, wenn Sie Büroflächen anmieten oder Co-Working nutzen?'),
(69, 2, 603, 'ISO/IEC 27001:2022', 'Anhang A', 'A.7.2', 'Zutrittskontrolle', 'offen', NULL, NULL, NULL, 603, 18, '2026-08-30 17:52:17', 18, '2026-09-22 11:40:04', 'Wie kontrollieren Sie den physischen Zutritt zu Ihren Geschäftsräumen?\nWerden Zutrittsberechtigungen dokumentiert und regelmäßig überprüft, z. B. Schlüssellisten, Zutrittskarten, Berechtigungsübersichten?\nWie protokollieren Sie den Zutritt zu besonders sensiblen Bereichen?\nWer ist für die Vergabe und den Entzug von Zutrittsrechten verantwortlich?'),
(70, 2, 604, 'ISO/IEC 27001:2022', 'Anhang A', 'A.7.3', 'Sicherung von Büros', 'offen', NULL, NULL, NULL, 604, 18, '2026-08-30 17:52:17', 18, '2026-09-22 11:40:04', 'Welche Maßnahmen verhindern unbefugten Zugriff auf Ihre Büros und Arbeitsplätze?\nWie ist sichergestellt, dass Besucher nicht unbeaufsichtigt in sensible Bereiche gelangen?\nWelche Vorkehrungen treffen Sie gegen Manipulation, z. B. abschließbare Schränke, Sichtschutz?\nWie dokumentieren Sie diese Schutzmaßnahmen?'),
(71, 2, 605, 'ISO/IEC 27001:2022', 'Anhang A', 'A.7.4', 'Physische Überwachung', 'offen', NULL, NULL, NULL, 605, 18, '2026-08-30 17:52:17', 18, '2026-09-22 11:40:04', 'Werden sicherheitsrelevante Bereiche physisch überwacht, z. B. durch Alarmanlagen, Bewegungsmelder oder Videoüberwachung?\nWie ist die Überwachung angemessen zum Schutzbedarf eines kleinen IT-Unternehmens gestaltet?\nWer wertet Überwachungsdaten aus und wie lange werden Aufzeichnungen aufbewahrt?\nWelche Nachweise belegen die Funktionsfähigkeit, z. B. Wartungsprotokolle, Testläufe?'),
(72, 2, 606, 'ISO/IEC 27001:2022', 'Anhang A', 'A.7.5', 'Schutz vor Umweltgefahren', 'offen', NULL, NULL, NULL, 606, 18, '2026-08-30 17:52:17', 18, '2026-09-22 11:40:04', 'Welche Schutzmaßnahmen haben Sie gegen Umwelteinflüsse wie Feuer, Wasser oder Stromausfall umgesetzt?\nWie schützen Sie kritische IT-Systeme vor Infrastrukturstörungen, z. B. durch USV, Rauchmelder, Wasserschutz?\nWelche Nachweise existieren, z. B. Wartungsprotokolle, Prüfberichte, Versicherungsunterlagen?\nWie berücksichtigen Sie diese Risiken bei einem angemieteten Büro oder Rechenzentrum?'),
(73, 2, 607, 'ISO/IEC 27001:2022', 'Anhang A', 'A.7.6', 'Arbeiten in gesicherten Bereichen', 'offen', NULL, NULL, NULL, 607, 18, '2026-08-30 17:52:17', 18, '2026-09-22 11:40:04', 'Welche Bereiche mit erhöhtem Schutzbedarf existieren und welche Regeln gelten dort für Tätigkeiten?\nWie werden Freigaben für Arbeiten in diesen Bereichen erteilt und dokumentiert?\nWer darf Wartungs- oder Installationsarbeiten durchführen und wie wird dies kontrolliert?\nWelche Nachweise belegen die Einhaltung, z. B. Freigabeprotokolle, Begleitregelungen für externe Techniker?'),
(74, 2, 608, 'ISO/IEC 27001:2022', 'Anhang A', 'A.7.7', 'Clear Desk / Clear Screen', 'offen', NULL, NULL, NULL, 608, 18, '2026-08-30 17:52:17', 18, '2026-09-22 11:40:04', 'Welche Vorgaben existieren für Clear Desk und Clear Screen an Ihren Arbeitsplätzen?\nWie stellen Sie sicher, dass sensible Informationen nicht offen einsehbar sind, z. B. Bildschirmsperre, verschlossene Schubladen?\nWo sind diese Regeln dokumentiert, z. B. in einer Arbeitsplatzrichtlinie oder IT-Nutzungsordnung?\nWie überprüfen Sie die Einhaltung im Alltag?'),
(75, 2, 609, 'ISO/IEC 27001:2022', 'Anhang A', 'A.7.8', 'Standortgebundene Geräte', 'offen', NULL, NULL, NULL, 609, 18, '2026-08-30 17:52:17', 18, '2026-09-22 11:40:04', 'Wie schützen Sie standortgebundene Geräte wie Server, Arbeitsplatzrechner oder Netzwerkkomponenten gegen Diebstahl und unbefugte Nutzung?\nWelche Maßnahmen sind umgesetzt, z. B. Kensington-Schlösser, abschließbare Schränke, BIOS-Passwörter?\nWer führt ein Inventar dieser Geräte und wie wird es gepflegt?\nWelche Nachweise belegen die Schutzmaßnahmen?'),
(76, 2, 610, 'ISO/IEC 27001:2022', 'Anhang A', 'A.7.9', 'Außerbetriebnahme von Geräten', 'offen', NULL, NULL, NULL, 610, 18, '2026-08-30 17:52:17', 18, '2026-09-22 11:40:04', 'Wie stellen Sie sicher, dass Daten bei Außerbetriebnahme oder Weitergabe von Geräten sicher gelöscht werden?\nWelches Verfahren nutzen Sie zur Datenlöschung, z. B. zertifizierte Löschsoftware, physische Zerstörung?\nWelche Nachweise dokumentieren die sichere Entsorgung, z. B. Löschprotokolle, Vernichtungszertifikate?\nWer ist für diesen Prozess verantwortlich?'),
(77, 2, 611, 'ISO/IEC 27001:2022', 'Anhang A', 'A.7.10', 'Lagerung von Datenträgern', 'offen', NULL, NULL, NULL, 611, 18, '2026-08-30 17:52:17', 18, '2026-09-22 11:40:04', 'Wie werden Datenträger entsprechend ihrem Schutzbedarf gelagert und verwaltet?\nWelche Maßnahmen gelten für Transport und Aufbewahrung, z. B. verschlossene Schränke, verschlüsselte Medien?\nFühren Sie ein Verzeichnis über Datenträger mit sensiblen Informationen?\nWie erfolgt die sichere Entsorgung nicht mehr benötigter Datenträger?'),
(78, 2, 612, 'ISO/IEC 27001:2022', 'Anhang A', 'A.7.11', 'Unterstützende Infrastruktur', 'offen', NULL, NULL, NULL, 612, 18, '2026-08-30 17:52:17', 18, '2026-09-22 11:40:04', 'Wie ist Ihre unterstützende Infrastruktur wie Stromversorgung, Klimatisierung oder Internetzugang gegen Ausfälle geschützt?\nWelche Maßnahmen sichern die Verfügbarkeit, z. B. USV, redundante Internetanbindung, Wartungsverträge?\nWer ist für die Überwachung und Wartung dieser Systeme verantwortlich?\nWelche Nachweise belegen regelmäßige Prüfungen, z. B. Wartungsprotokolle?'),
(79, 2, 613, 'ISO/IEC 27001:2022', 'Anhang A', 'A.7.12', 'Kabelschutz', 'offen', NULL, NULL, NULL, 613, 18, '2026-08-30 17:52:17', 18, '2026-09-22 11:40:04', 'Wie schützen Sie Strom- und Datenkabel gegen Beschädigung, Abhören oder Manipulation?\nWelche Maßnahmen sind umgesetzt, z. B. Kabelkanäle, getrennte Verlegung, Zugangsbeschränkungen zu Verteilerräumen?\nWie ist die Verkabelung dokumentiert, z. B. in einem Netzwerkplan?\nWer prüft regelmäßig die Integrität der Verkabelung?'),
(80, 2, 614, 'ISO/IEC 27001:2022', 'Anhang A', 'A.7.13', 'Wartung von Geräten', 'offen', NULL, NULL, NULL, 614, 18, '2026-08-30 17:52:17', 18, '2026-09-22 11:40:04', 'Wie stellen Sie sicher, dass Wartung und Reparatur von Geräten kontrolliert und nachvollziehbar erfolgen?\nWelche Regeln gelten für externe Dienstleister bei Wartungsarbeiten, z. B. Begleitung, Vertraulichkeitsvereinbarung?\nWelche Nachweise dokumentieren durchgeführte Wartungen, z. B. Wartungsprotokolle, Serviceberichte, Ticketeinträge?\nWie wird vor Wartung sichergestellt, dass sensible Daten geschützt sind?'),
(81, 2, 615, 'ISO/IEC 27001:2022', 'Anhang A', 'A.7.14', 'Entsorgung', 'offen', NULL, NULL, NULL, 615, 18, '2026-08-30 17:52:17', 18, '2026-09-22 11:40:50', 'Wie stellen Sie sicher, dass ausgemusterte Laptops, Festplatten oder USB-Sticks vor Weitergabe oder Entsorgung vollständig von Daten bereinigt werden?\nWelche Verfahren nutzen Sie zur sicheren Datenlöschung oder physischen Zerstörung, z. B. Löschsoftware mit Protokoll, Schredder-Dienstleister?\nWer entscheidet, ob ein Gerät wiederverwendet oder entsorgt wird, und wie wird dies dokumentiert?\nWie gehen Sie mit defekten Datenträgern um, die sich nicht mehr softwareseitig löschen lassen?'),
(82, 2, 616, 'ISO/IEC 27001:2022', 'Anhang A', 'A.8.1', 'Endgerätesicherheit', 'offen', NULL, NULL, NULL, 616, 18, '2026-08-30 17:52:17', 18, '2026-09-22 11:40:50', 'Welche Härtungsmaßnahmen setzen Sie auf Entwickler-Laptops und anderen Endgeräten um, z. B. deaktivierte Dienste, Festplattenverschlüsselung, Firewall?\nWie stellen Sie sicher, dass Betriebssysteme und Anwendungen zeitnah aktualisiert werden?\nWelche Vorgaben existieren für den Einsatz privater Geräte oder mobiler Endgeräte im Firmennetz?\nWie wird die Einhaltung der Endgerätekonfiguration überprüft – gibt es eine Baseline oder Checkliste?'),
(83, 2, 617, 'ISO/IEC 27001:2022', 'Anhang A', 'A.8.2', 'Privilegierte Zugriffe', 'offen', NULL, NULL, NULL, 617, 18, '2026-08-30 17:52:17', 18, '2026-09-22 11:40:50', 'Wer verfügt in Ihrem kleinen Team über privilegierte Zugriffsrechte, z. B. Admin-Konten für Server, Cloud-Konsolen oder Datenbanken?\nWie trennen Sie administrative von regulären Benutzerkonten im Tagesgeschäft?\nWelche Kontrollen oder Genehmigungsverfahren gelten für die Vergabe und Nutzung privilegierter Rechte?\nWie protokollieren und überwachen Sie Aktionen mit erhöhten Rechten, z. B. Audit-Logs, Benachrichtigungen?'),
(84, 2, 618, 'ISO/IEC 27001:2022', 'Anhang A', 'A.8.3', 'Informationszugriff', 'offen', NULL, NULL, NULL, 618, 18, '2026-08-30 17:52:17', 18, '2026-09-22 11:40:50', 'Wie setzen Sie technisch durch, dass nur berechtigte Personen auf bestimmte Informationen und Systeme zugreifen können, z. B. Rollenkonzept, Gruppenberechtigungen?\nWelche Systeme protokollieren Zugriffe und wie lange bewahren Sie diese Protokolle auf?\nWie überprüfen Sie regelmäßig, ob vergebene Zugriffsrechte noch angemessen sind?'),
(85, 2, 619, 'ISO/IEC 27001:2022', 'Anhang A', 'A.8.4', 'Quellcodezugriff', 'offen', NULL, NULL, NULL, 619, 18, '2026-08-30 17:52:17', 18, '2026-09-22 11:40:50', 'Wo wird der Quellcode Ihrer ISMS-Software gespeichert und wer hat darauf Zugriff, z. B. Git-Repository, Cloud-Dienst?\nWelche Zugriffskontrollen schützen das Repository vor unbefugter Einsicht oder Änderungen, z. B. Branch-Protection, Code-Review-Pflicht?\nWie stellen Sie die Nachvollziehbarkeit von Änderungen sicher, z. B. Commit-Historie, signierte Commits?\nWelche Maßnahmen verhindern, dass Quellcode unkontrolliert das Unternehmen verlässt?'),
(86, 2, 620, 'ISO/IEC 27001:2022', 'Anhang A', 'A.8.5', 'Sichere Authentisierung', 'offen', NULL, NULL, NULL, 620, 18, '2026-08-30 17:52:17', 18, '2026-09-22 11:40:50', 'Welche Authentisierungsverfahren setzen Sie für kritische Systeme ein, z. B. Cloud-Konsolen, Repository, Produktivumgebung?\nWo nutzen Sie Mehrfaktor-Authentisierung und nach welchen Kriterien entscheiden Sie über deren Einsatz?\nWie stellen Sie sicher, dass Passwörter ausreichend stark sind und nicht mehrfach verwendet werden?\nWelche Vorgaben gelten für die Authentisierung gegenüber Ihrer SaaS-Plattform durch Kunden?'),
(87, 2, 621, 'ISO/IEC 27001:2022', 'Anhang A', 'A.8.6', 'Kapazitätsmanagement', 'offen', NULL, NULL, NULL, 621, 18, '2026-08-30 17:52:17', 18, '2026-09-22 11:40:50', 'Wie überwachen Sie die Auslastung Ihrer Cloud-Ressourcen oder Server, z. B. CPU, Speicher, Datenbankkapazität?\nWelche Schwellenwerte oder Alarme haben Sie definiert, um Engpässe frühzeitig zu erkennen?\nWie planen Sie Kapazitäten für Lastspitzen, etwa bei steigender Kundenzahl Ihrer ISMS-Software?\nWelche Dokumentation oder Aufzeichnungen belegen Ihre Kapazitätsplanung?'),
(88, 2, 622, 'ISO/IEC 27001:2022', 'Anhang A', 'A.8.7', 'Malware-Schutz', 'offen', NULL, NULL, NULL, 622, 18, '2026-08-30 17:52:17', 18, '2026-09-22 11:40:50', 'Welche Schutzmaßnahmen gegen Schadsoftware setzen Sie auf Endgeräten und Servern ein, z. B. Antivirus, EDR-Lösung?\nWie stellen Sie sicher, dass Signaturen und Schutzmechanismen aktuell bleiben?\nWie werden erkannte Bedrohungen gemeldet und behandelt?\nGibt es Ausnahmen vom Malware-Schutz und wie werden diese dokumentiert und begründet?'),
(89, 2, 623, 'ISO/IEC 27001:2022', 'Anhang A', 'A.8.8', 'Technische Schwachstellen', 'offen', NULL, NULL, NULL, 623, 18, '2026-08-30 17:52:17', 18, '2026-09-22 11:40:50', 'Wie erfahren Sie von neuen Schwachstellen in den von Ihnen eingesetzten Komponenten, z. B. CVE-Feeds, Herstellermeldungen, Dependency-Scanner?\nNach welchen Kriterien bewerten und priorisieren Sie Schwachstellen für Ihre Umgebung?\nWie schnell werden kritische Patches eingespielt und wie dokumentieren Sie dies?\nWie gehen Sie mit Schwachstellen um, für die noch kein Patch verfügbar ist?'),
(90, 2, 624, 'ISO/IEC 27001:2022', 'Anhang A', 'A.8.9', 'Konfigurationsmanagement', 'offen', NULL, NULL, NULL, 624, 18, '2026-08-30 17:52:17', 18, '2026-09-22 11:40:50', 'Welche sicheren Basiskonfigurationen haben Sie für Server, Cloud-Dienste und Entwicklungsumgebungen definiert, z. B. Hardening-Guides, Konfigurations-Templates?\nWie stellen Sie sicher, dass Konfigurationen nicht unautorisiert verändert werden, z. B. Infrastructure-as-Code, Änderungsprotokolle?\nWie oft überprüfen Sie, ob aktuelle Konfigurationen noch den Vorgaben entsprechen?'),
(91, 2, 625, 'ISO/IEC 27001:2022', 'Anhang A', 'A.8.10', 'Informationslöschung', 'offen', NULL, NULL, NULL, 625, 18, '2026-08-30 17:52:17', 18, '2026-09-22 11:40:50', 'Welche Verfahren nutzen Sie, um Daten auf Speichermedien oder in Cloud-Diensten sicher zu löschen, z. B. kryptografisches Löschen, Überschreiben?\nWie stellen Sie sicher, dass auch Backups und Replikate berücksichtigt werden?\nWie dokumentieren Sie durchgeführte Löschvorgänge, z. B. Löschprotokolle?\nWelche gesetzlichen Aufbewahrungsfristen beachten Sie vor einer Löschung?'),
(92, 2, 626, 'ISO/IEC 27001:2022', 'Anhang A', 'A.8.11', 'Datenmaskierung', 'offen', NULL, NULL, NULL, 626, 18, '2026-08-30 17:52:17', 18, '2026-09-22 11:40:50', 'In welchen Szenarien arbeiten Sie mit maskierten oder reduzierten Daten, z. B. in Test- oder Entwicklungsumgebungen Ihrer ISMS-Software?\nWelche Techniken setzen Sie zur Datenmaskierung ein, z. B. Anonymisierung, Pseudonymisierung, synthetische Daten?\nWie stellen Sie sicher, dass Produktivdaten nicht ungeschützt in Testumgebungen gelangen?'),
(93, 2, 627, 'ISO/IEC 27001:2022', 'Anhang A', 'A.8.12', 'Datenverlustprävention', 'offen', NULL, NULL, NULL, 627, 18, '2026-08-30 17:52:17', 18, '2026-09-22 11:40:50', 'Welche Mechanismen verhindern, dass sensible Daten unkontrolliert das Unternehmen verlassen, z. B. E-Mail-Filter, Cloud-Freigaben, USB-Einschränkungen?\nWie erkennen Sie ungewöhnliche Datenabflüsse oder -übertragungen?\nWelche Richtlinien gelten für den Umgang mit Kundendaten aus Ihrer SaaS-Plattform?\nWie sensibilisieren Sie Ihr Team für die Risiken unerlaubter Datenübertragung?'),
(94, 2, 628, 'ISO/IEC 27001:2022', 'Anhang A', 'A.8.13', 'Datensicherung', 'offen', NULL, NULL, NULL, 628, 18, '2026-08-30 17:52:17', 18, '2026-09-22 11:40:50', 'Welche Daten und Systeme werden wie häufig gesichert, z. B. Quellcode, Kundendaten, Konfigurationen?\nWo werden Backups aufbewahrt und wie sind sie vor unbefugtem Zugriff geschützt, z. B. Verschlüsselung, separater Standort?\nWann haben Sie zuletzt eine Wiederherstellung getestet und was war das Ergebnis?\nWie schnell könnten Sie nach einem Datenverlust den Betrieb Ihrer ISMS-Software wiederherstellen?'),
(95, 2, 629, 'ISO/IEC 27001:2022', 'Anhang A', 'A.8.14', 'Redundanz', 'offen', NULL, NULL, NULL, 629, 18, '2026-08-30 17:52:17', 18, '2026-09-22 11:40:50', 'Welche Verfügbarkeitsziele haben Sie für Ihre SaaS-Plattform definiert und wo sind diese dokumentiert?\nWelche Redundanzen nutzen Sie, um Ausfälle abzufangen, z. B. mehrstufige Cloud-Regionen, Datenbank-Replikation?\nWie haben Sie getestet, ob ein Failover im Ernstfall funktioniert?\nWie gehen Sie mit Single-Points-of-Failure in Ihrer Infrastruktur um?'),
(96, 2, 630, 'ISO/IEC 27001:2022', 'Anhang A', 'A.8.15', 'Protokollierung', 'offen', NULL, NULL, NULL, 630, 18, '2026-08-30 17:52:17', 18, '2026-09-22 11:40:50', 'Welche sicherheitsrelevanten Ereignisse werden protokolliert, z. B. Anmeldeversuche, Rechtevergabe, Systemänderungen?\nWo werden Logs gespeichert und wie schützen Sie sie vor Manipulation oder vorzeitiger Löschung?\nWie lange bewahren Sie Protokolle auf und welche Vorgaben liegen dem zugrunde?\nWer hat Zugriff auf die Logs und wie ist dieser Zugriff eingeschränkt?'),
(97, 2, 631, 'ISO/IEC 27001:2022', 'Anhang A', 'A.8.16', 'Monitoring', 'offen', NULL, NULL, NULL, 631, 18, '2026-08-30 17:52:17', 18, '2026-09-22 11:40:50', 'Wie überwachen Sie Ihre Systeme auf Anomalien, verdächtige Aktivitäten oder Angriffe, z. B. Alerting, SIEM, Cloud-Monitoring?\nWelche Schwellenwerte oder Regeln lösen Alarme aus und wer wird benachrichtigt?\nWie schnell reagieren Sie auf erkannte Abweichungen und wie ist der Prozess dokumentiert?\nWie stellen Sie sicher, dass Alarme nicht übersehen werden – auch außerhalb der Geschäftszeiten?'),
(98, 2, 632, 'ISO/IEC 27001:2022', 'Anhang A', 'A.8.17', 'Uhrzeitsynchronisation', 'offen', NULL, NULL, NULL, 632, 18, '2026-08-30 17:52:17', 18, '2026-09-22 11:40:50', 'Wie stellen Sie sicher, dass alle Systeme eine einheitliche Zeitquelle nutzen, z. B. NTP-Server, Cloud-Zeitdienst?\nWelche Systeme sind an die zentrale Zeitquelle angebunden und wie überprüfen Sie die Synchronisation?\nWie würden Sie Abweichungen der Systemzeit erkennen und korrigieren?'),
(99, 2, 633, 'ISO/IEC 27001:2022', 'Anhang A', 'A.8.18', 'Nutzung privilegierter Programme', 'offen', NULL, NULL, NULL, 633, 18, '2026-08-30 17:52:17', 18, '2026-09-22 11:40:50', 'Welche administrativen Tools und Befehle stehen Ihrem Team zur Verfügung, z. B. Remote-Shells, Datenbank-Clients, Cloud-CLIs?\nWie kontrollieren und beschränken Sie den Einsatz solcher privilegierten Programme?\nWie wird die Nutzung dieser Tools protokolliert und nachvollziehbar gemacht?\nGibt es Vorgaben, wann und durch wen solche Programme eingesetzt werden dürfen?'),
(100, 2, 634, 'ISO/IEC 27001:2022', 'Anhang A', 'A.8.19', 'Softwareinstallation', 'offen', NULL, NULL, NULL, 634, 18, '2026-08-30 17:52:17', 18, '2026-09-22 11:40:50', 'Wie stellen Sie sicher, dass nur freigegebene Software auf Arbeitsgeräten und Servern installiert wird?\nWelche Freigabe- oder Genehmigungsverfahren gelten für neue Software, z. B. Freigabeliste, Prüfung durch Verantwortlichen?\nWie überprüfen Sie die Herkunft und Integrität von Software vor der Installation, z. B. Signaturen, offizielle Quellen?\nWie verhindern Sie die Installation nicht autorisierter Programme?'),
(101, 2, 635, 'ISO/IEC 27001:2022', 'Anhang A', 'A.8.20', 'Netzwerksicherheit', 'offen', NULL, NULL, NULL, 635, 18, '2026-08-30 17:52:17', 18, '2026-09-22 11:41:22', 'Wie ist Ihr Netzwerk aktuell strukturiert und nach welchen Kriterien haben Sie Segmente gebildet?\nWelche Schutzbedarfsstufen unterscheiden Sie für Ihre Netzwerkbereiche, z. B. Entwicklung, SaaS-Infrastruktur, Büronetz?\nWie sind externe Verbindungen zu Kunden oder Cloud-Diensten abgesichert, und welche Firewall-Regeln oder VPN-Konfigurationen dokumentieren dies?\nWer ist für die Pflege der Netzwerksicherheitsregeln verantwortlich, und wo ist dies festgehalten?'),
(102, 2, 636, 'ISO/IEC 27001:2022', 'Anhang A', 'A.8.21', 'Netzwerkdienste', 'offen', NULL, NULL, NULL, 636, 18, '2026-08-30 17:52:17', 18, '2026-09-22 11:41:22', 'Welche Netzwerkdienste betreiben Sie intern oder extern, und wie stellen Sie sicher, dass nur benötigte Dienste aktiv sind?\nWie überwachen Sie Ihre Netzwerkdienste auf Verfügbarkeit und sicherheitsrelevante Ereignisse?\nWelche Dokumentation belegt die sichere Konfiguration Ihrer Dienste, z. B. Härtungsrichtlinien, Konfigurationsdateien, Monitoring-Dashboards?'),
(103, 2, 637, 'ISO/IEC 27001:2022', 'Anhang A', 'A.8.22', 'Trennung von Netzwerken', 'offen', NULL, NULL, NULL, 637, 18, '2026-08-30 17:52:17', 18, '2026-09-22 11:41:22', 'Wie trennen Sie Netzwerksegmente technisch voneinander, z. B. durch VLANs, Firewalls oder separate Netze?\nWie verhindern Sie, dass ein kompromittiertes System auf andere Segmente wie Ihre SaaS-Produktionsumgebung übergreifen kann?\nWelche Nachweise existieren für die Segmentierung, z. B. Netzwerkdiagramme, Firewall-Regelwerke, VLAN-Konfigurationen?'),
(104, 2, 638, 'ISO/IEC 27001:2022', 'Anhang A', 'A.8.23', 'Webfilterung', 'offen', NULL, NULL, NULL, 638, 18, '2026-08-30 17:52:17', 18, '2026-09-22 11:41:22', 'Gibt es Vorgaben, welche Webseiten oder Kategorien von Ihren Mitarbeitern aufgerufen werden dürfen?\nWelche technischen Maßnahmen setzen Sie ein, um Zugriffe auf schädliche Inhalte zu blockieren, z. B. DNS-Filter, Proxy, Endpoint-Protection?\nWie dokumentieren Sie diese Richtlinien und deren Umsetzung, z. B. Filterprofile, Protokolle blockierter Zugriffe?'),
(105, 2, 639, 'ISO/IEC 27001:2022', 'Anhang A', 'A.8.24', 'Kryptografische Verfahren', 'offen', NULL, NULL, NULL, 639, 18, '2026-08-30 17:52:17', 18, '2026-09-22 11:41:22', 'Für welche Anwendungsfälle setzen Sie Verschlüsselung ein, z. B. Datenübertragung zur SaaS-Plattform, Speicherung von Kundendaten?\nNach welchen Kriterien wählen Sie Verschlüsselungsverfahren und Schlüssellängen aus?\nWelche Dokumentation belegt Ihre Kryptografie-Richtlinie und deren Umsetzung, z. B. TLS-Konfigurationen, Verschlüsselungskonzept?'),
(106, 2, 640, 'ISO/IEC 27001:2022', 'Anhang A', 'A.8.25', 'Schlüsselmanagement', 'offen', NULL, NULL, NULL, 640, 18, '2026-08-30 17:52:17', 18, '2026-09-22 11:41:22', 'Wie erzeugen, speichern und schützen Sie kryptografische Schlüssel für Ihre SaaS-Anwendung und interne Systeme?\nWelches Verfahren nutzen Sie für Schlüsselrotation und wie dokumentieren Sie die Außerbetriebnahme alter Schlüssel?\nWo sind Verantwortlichkeiten und Prozesse für das Schlüsselmanagement festgelegt, z. B. Key-Management-Richtlinie, HSM-Dokumentation?'),
(107, 2, 641, 'ISO/IEC 27001:2022', 'Anhang A', 'A.8.26', 'Sichere Entwicklung', 'offen', NULL, NULL, NULL, 641, 18, '2026-08-30 17:52:17', 18, '2026-09-22 11:41:22', 'Wie stellen Sie sicher, dass Sicherheitsanforderungen von Beginn an in Ihre Softwareentwicklung einfließen?\nWelche Rollen und Verantwortlichkeiten für sichere Entwicklung haben Sie definiert?\nWelche Dokumente beschreiben Ihren sicheren Entwicklungsprozess, z. B. Entwicklungsrichtlinie, Security-Requirements, Definition of Done?'),
(108, 2, 642, 'ISO/IEC 27001:2022', 'Anhang A', 'A.8.27', 'Sichere Architektur', 'offen', NULL, NULL, NULL, 642, 18, '2026-08-30 17:52:17', 18, '2026-09-22 11:41:22', 'Nach welchen Sicherheitsprinzipien entwerfen Sie die Architektur Ihrer ISMS-Software, z. B. Least Privilege, Defense in Depth?\nWie dokumentieren Sie Architekturentscheidungen unter Sicherheitsaspekten, z. B. Architekturdiagramme, Threat Models?\nWer prüft neue Systemdesigns auf Einhaltung dieser Prinzipien, und wie ist dieser Review-Prozess geregelt?'),
(109, 2, 643, 'ISO/IEC 27001:2022', 'Anhang A', 'A.8.28', 'Sicheres Coding', 'offen', NULL, NULL, NULL, 643, 18, '2026-08-30 17:52:17', 18, '2026-09-22 11:41:22', 'Welche Coding-Standards oder Richtlinien nutzen Sie, um typische Sicherheitslücken wie Injection oder XSS zu vermeiden?\nWie führen Sie Code-Reviews durch, und welche Sicherheitsaspekte werden dabei geprüft?\nWelche Nachweise gibt es für die Einhaltung dieser Standards, z. B. Coding Guidelines, Review-Protokolle, statische Code-Analyse-Berichte?'),
(110, 2, 644, 'ISO/IEC 27001:2022', 'Anhang A', 'A.8.29', 'Sicherheitstests', 'offen', NULL, NULL, NULL, 644, 18, '2026-08-30 17:52:17', 18, '2026-09-22 11:41:22', 'Welche Sicherheitstests führen Sie vor der Produktivsetzung durch, z. B. Penetrationstests, SAST, DAST, manuelle Reviews?\nWie planen Sie diese Tests, und wer ist für Durchführung und Nachverfolgung von Findings verantwortlich?\nWelche Dokumentation belegt die Testergebnisse und deren Behebung, z. B. Testberichte, Issue-Tracker, Abnahmeprotokolle?'),
(111, 2, 645, 'ISO/IEC 27001:2022', 'Anhang A', 'A.8.30', 'Externe Entwicklung', 'offen', NULL, NULL, NULL, 645, 18, '2026-08-30 17:52:17', 18, '2026-09-22 11:41:22', 'Beauftragen Sie externe Entwickler oder Dienstleister für Teile Ihrer Software, und falls ja, für welche Komponenten?\nWie stellen Sie vertraglich sicher, dass externe Partner Ihre Sicherheitsanforderungen einhalten?\nWelche Nachweise fordern Sie von externen Entwicklern ein, z. B. Sicherheitstests, Code-Reviews, Vertraulichkeitsvereinbarungen?'),
(112, 2, 646, 'ISO/IEC 27001:2022', 'Anhang A', 'A.8.31', 'Produktionsumgebung', 'offen', NULL, NULL, NULL, 646, 18, '2026-08-30 17:52:17', 18, '2026-09-22 11:41:22', 'Wie schützen Sie Ihre SaaS-Produktionsumgebung vor unbefugtem Zugriff und unautorisierten Änderungen?\nWer hat Zugriff auf Produktionssysteme, und wie ist dieser Zugriff dokumentiert und kontrolliert?\nWelche Nachweise existieren für den Schutz der Produktionsumgebung, z. B. Zugriffsrechtelisten, Härtungsdokumentation, Änderungsprotokolle?');
INSERT INTO `aud_pruefpunkte` (`id`, `audit_id`, `norm_id`, `norm`, `kapitel`, `nummer`, `titel`, `bewertung`, `feststellung`, `nachweis`, `abweichung_id`, `sortierung`, `Ersteller`, `erstellt`, `Aenderer`, `geaendert`, `beschreibung`) VALUES
(113, 2, 647, 'ISO/IEC 27001:2022', 'Anhang A', 'A.8.32', 'Änderungsmanagement', 'offen', NULL, NULL, NULL, 647, 18, '2026-08-30 17:52:17', 18, '2026-09-22 11:41:22', 'Wie läuft Ihr Änderungsmanagement ab, von der Beantragung über Bewertung bis zur Freigabe und Umsetzung?\nWer genehmigt Änderungen an Systemen und Software, und wie dokumentieren Sie diese Freigaben?\nWelche Aufzeichnungen führen Sie über durchgeführte Änderungen, z. B. Change-Tickets, Deployment-Logs, Freigabeprotokolle?'),
(114, 2, 648, 'ISO/IEC 27001:2022', 'Anhang A', 'A.8.33', 'Testdaten', 'offen', NULL, NULL, NULL, 648, 18, '2026-08-30 17:52:17', 18, '2026-09-22 11:41:22', 'Wie gehen Sie mit Testdaten um, insbesondere wenn diese echte Kundendaten oder personenbezogene Daten enthalten könnten?\nWelche Maßnahmen setzen Sie ein, um Vertraulichkeit zu wahren, z. B. Anonymisierung, Maskierung, synthetische Daten?\nWelche Dokumentation belegt Ihre Vorgehensweise, z. B. Testdatenrichtlinie, Anonymisierungsprotokolle?'),
(115, 2, 649, 'ISO/IEC 27001:2022', 'Anhang A', 'A.8.34', 'Trennung Test/Produktion', 'offen', NULL, NULL, NULL, 649, 18, '2026-08-30 17:52:17', 18, '2026-09-22 11:41:22', 'Wie trennen Sie Ihre Test- und Entwicklungsumgebungen von der Produktionsumgebung Ihrer SaaS-Plattform?\nWelche technischen und organisatorischen Maßnahmen verhindern, dass Produktivdaten in Testumgebungen gelangen oder Tests die Produktion beeinflussen?\nWelche Nachweise dokumentieren diese Trennung, z. B. Umgebungsübersicht, Netzwerkdiagramme, Zugriffsregelungen?'),
(116, 3, 1733, 'NIS2', 'Kap. I – Allgemeine Bestimmungen', 'Art. 2', 'Geltungsbereich – Betroffene Einrichtungen', 'offen', NULL, NULL, NULL, 1733, 18, '2026-09-22 06:33:28', 18, '2026-09-22 07:34:37', 'Die Anforderung verlangt eine systematische Selbsteinschätzung, ob die Organisation unter die NIS2-Richtlinie fällt. Geprüft wird, ob eine nachvollziehbare Analyse der Sektorzugehörigkeit (Anhang I/II), der Größenkriterien (Mitarbeiterzahl, Umsatz) und der Konzernverflechtungen vorliegt. Typische Lücken sind fehlende Dokumentation der Einstufungsentscheidung oder unberücksichtigte Tochtergesellschaften. Nachweise umfassen die schriftliche Einstufungsdokumentation, Organigramme, Geschäftsberichte und einen Prozess zur regelmäßigen Überprüfung bei Strukturänderungen.'),
(117, 3, 1734, 'NIS2', 'Kap. I – Allgemeine Bestimmungen', 'Art. 3', 'Registrierung wesentlicher und wichtiger Einrichtungen', 'offen', NULL, NULL, NULL, 1734, 18, '2026-09-22 06:33:28', 18, '2026-09-22 07:34:37', 'Die Anforderung fordert die fristgerechte Registrierung beim BSI mit vollständigen Angaben wie Name, Kontaktdaten, Sektorzugehörigkeit und IP-Adressbereichen sowie einen benannten Ansprechpartner. Prüffragen zielen auf die Einhaltung der Fristen, die Vollständigkeit der Angaben und den Aktualisierungsprozess bei Änderungen. Häufige Lücken sind verspätete Registrierungen oder fehlende 24/7-Erreichbarkeit bei kritischen Einrichtungen. Nachweise sind Registrierungsbestätigungen, Korrespondenz mit dem BSI und interne Prozessbeschreibungen zur Datenpflege.'),
(118, 3, 1735, 'NIS2', 'Kap. II – Koordinierung', 'Art. 8', 'Zuständige Behörden und zentrale Anlaufstellen', 'offen', NULL, NULL, NULL, 1735, 18, '2026-09-22 06:33:28', 18, '2026-09-22 07:34:37', 'Die Anforderung verlangt, dass die Organisation ihre zuständigen Aufsichtsbehörden kennt und Kommunikationswege etabliert hat. Geprüft wird, ob das BSI und ggf. weitere sektorale Behörden identifiziert sind und eine interne Kontaktperson für behördliche Anfragen benannt wurde. Typische Lücken sind unklare Zuständigkeiten oder fehlende Prozesse für behördliche Meldungen. Nachweise umfassen Kontaktlisten, Organigramme mit benannten Ansprechpartnern und dokumentierte Kommunikationsprozesse.'),
(119, 3, 1736, 'NIS2', 'Kap. IV – Risikomanagement', 'Art. 20', 'Governance – Verantwortung der Leitungsorgane', 'offen', NULL, NULL, NULL, 1736, 18, '2026-09-22 06:33:28', 18, '2026-09-22 07:34:37', 'Die Anforderung stellt die persönliche Verantwortung der Geschäftsleitung für Cybersicherheit in den Mittelpunkt. Geprüft wird, ob das Leitungsorgan Sicherheitsmaßnahmen genehmigt, deren Umsetzung überwacht und selbst regelmäßig geschult wird. Typische Lücken sind fehlende Schulungsnachweise der Geschäftsführung oder unzureichende Berichterstattung an die Leitung. Nachweise sind Schulungszertifikate, Protokolle von Leitungssitzungen, Bestellungsurkunden eines CISO und regelmäßige Management-Reports zur Cybersicherheitslage.'),
(120, 3, 1737, 'NIS2', 'Kap. IV – Risikomanagement', 'Art. 21 Abs. 1', 'Risikomanagement – Allgemeine Verpflichtung', 'offen', NULL, NULL, NULL, 1737, 18, '2026-09-22 06:33:28', 18, '2026-09-22 07:34:37', 'Die Anforderung fordert ein dokumentiertes Risikomanagement-Framework, das Cybersicherheitsrisiken systematisch identifiziert, bewertet und behandelt. Geprüft wird, ob ein All-Hazard-Ansatz verfolgt wird und Maßnahmen verhältnismäßig zur Größe und Risiko der Organisation sind. Typische Lücken sind veraltete Risikoanalysen oder fehlende Berichte an das Leitungsorgan. Nachweise umfassen Risikomanagement-Richtlinien, Risikoregister, Behandlungspläne und Protokolle der jährlichen Überprüfung.'),
(121, 3, 1738, 'NIS2', 'Kap. IV – Risikomanagement', 'Art. 21 Abs. 2a', 'Risikoanalyse und Sicherheitskonzepte für Informationssysteme', 'offen', NULL, NULL, NULL, 1738, 18, '2026-09-22 06:33:28', 18, '2026-09-22 07:34:37', 'Die Anforderung verlangt dokumentierte Konzepte zur Risikoanalyse und eine genehmigte Informationssicherheitsrichtlinie. Geprüft wird, ob Schutzbedarfsfeststellungen für IT-Systeme vorliegen, Restrisiken durch die Leitung akzeptiert sind und externe Bedrohungslagen einbezogen werden. Typische Lücken sind fehlende oder veraltete IS-Policies sowie nicht dokumentierte Risikoakzeptanzen. Nachweise sind die IS-Policy, Schutzbedarfsanalysen, Risk Treatment Plans und Protokolle der Risikoakzeptanz durch die Geschäftsleitung.'),
(122, 3, 1739, 'NIS2', 'Kap. IV – Risikomanagement', 'Art. 21 Abs. 2b', 'Bewältigung von Sicherheitsvorfällen (Incident Handling)', 'offen', NULL, NULL, NULL, 1739, 18, '2026-09-22 06:33:28', 18, '2026-09-22 07:34:37', 'Die Anforderung fordert dokumentierte Verfahren zur Bewältigung von Sicherheitsvorfällen einschließlich eines getesteten Incident-Response-Plans. Geprüft wird, ob Rollen, Eskalationsstufen und Klassifizierungsschemata definiert sind sowie Lessons-Learned-Prozesse und regelmäßige Übungen stattfinden. Typische Lücken sind ungetestete Pläne oder fehlende forensische Sicherungsprozesse. Nachweise umfassen den IRP, Übungsprotokolle, Vorfallsberichte, Eskalationsmatrizen und Dokumentation durchgeführter Nachbereitungen.'),
(123, 3, 1740, 'NIS2', 'Kap. IV – Risikomanagement', 'Art. 21 Abs. 2c', 'Business Continuity und Krisenmanagement', 'offen', NULL, NULL, NULL, 1740, 18, '2026-09-22 06:33:28', 18, '2026-09-22 07:34:37', 'Die Anforderung verlangt dokumentierte Business-Continuity- und Krisenmanagementpläne für Cybervorfälle mit definierten RTO/RPO-Werten. Geprüft wird, ob Backup-Strategien getestet, ein Krisenmanagementteam benannt und Krisenkommunikationspläne vorhanden sind. Typische Lücken sind ungetestete Wiederherstellungsverfahren oder fehlende jährliche BCM-Übungen. Nachweise sind BCP, DRP, Testprotokolle, Backup-Wiederherstellungsnachweise und Dokumentation des Krisenmanagementteams.'),
(124, 3, 1741, 'NIS2', 'Kap. IV – Risikomanagement', 'Art. 21 Abs. 2d', 'Sicherheit der Lieferkette (Supply Chain Security)', 'offen', NULL, NULL, NULL, 1741, 18, '2026-09-22 06:33:28', 18, '2026-09-22 07:34:37', 'Die Anforderung fordert die Berücksichtigung von Cybersicherheitsrisiken in Lieferantenbeziehungen. Geprüft wird, ob ein Lieferanteninventar mit Risikokategorisierung existiert, Sicherheitsanforderungen vertraglich verankert sind und regelmäßige Bewertungen kritischer Lieferanten stattfinden. Typische Lücken sind fehlende Exit-Strategien oder nicht einbezogene Sub-Auftragnehmer. Nachweise umfassen Lieferantenlisten, Vertragsklauseln, Audit-Berichte, Zertifikate der Lieferanten und Exit-Management-Pläne.'),
(125, 3, 1742, 'NIS2', 'Kap. IV – Risikomanagement', 'Art. 21 Abs. 2e', 'Sicherheit in Erwerb, Entwicklung und Wartung von IT-Systemen', 'offen', NULL, NULL, NULL, 1742, 18, '2026-09-22 06:33:28', 18, '2026-09-22 07:34:37', 'Die Anforderung verlangt Sicherheit beim Erwerb, der Entwicklung und Wartung von IT-Systemen. Geprüft wird, ob Sicherheitsanforderungen in Ausschreibungen enthalten sind, ein Secure Development Lifecycle sowie Schwachstellen- und Patch-Management etabliert sind. Typische Lücken sind fehlende Sicherheitstests vor Produktivsetzung oder nicht dokumentierte Coding Guidelines. Nachweise sind Lastenhefte mit Sicherheitsanforderungen, SSDLC-Dokumentation, Penetrationstest-Berichte, Patch-Management-Prozesse und Schwachstellenregister.'),
(126, 3, 1743, 'NIS2', 'Kap. IV – Risikomanagement', 'Art. 21 Abs. 2f', 'Bewertung der Wirksamkeit von Risikomanagementmaßnahmen', 'offen', NULL, NULL, NULL, 1743, 18, '2026-09-22 06:33:28', NULL, NULL, NULL),
(127, 3, 1744, 'NIS2', 'Kap. IV – Risikomanagement', 'Art. 21 Abs. 2g', 'Cyberhygiene und Schulungen zur Cybersicherheit', 'offen', NULL, NULL, NULL, 1744, 18, '2026-09-22 06:33:28', NULL, NULL, NULL),
(128, 3, 1745, 'NIS2', 'Kap. IV – Risikomanagement', 'Art. 21 Abs. 2h', 'Kryptographie und Verschlüsselung', 'offen', NULL, NULL, NULL, 1745, 18, '2026-09-22 06:33:28', NULL, NULL, NULL),
(129, 3, 1746, 'NIS2', 'Kap. IV – Risikomanagement', 'Art. 21 Abs. 2i', 'Personalsicherheit, Zugriffskontrolle und Asset-Management', 'offen', NULL, NULL, NULL, 1746, 18, '2026-09-22 06:33:28', NULL, NULL, NULL),
(130, 3, 1747, 'NIS2', 'Kap. IV – Risikomanagement', 'Art. 21 Abs. 2j', 'Multi-Faktor-Authentifizierung und sichere Kommunikation', 'offen', NULL, NULL, NULL, 1747, 18, '2026-09-22 06:33:28', NULL, NULL, NULL),
(131, 3, 1748, 'NIS2', 'Kap. IV – Risikomanagement', 'Art. 21 Abs. 3', 'Europäische Cybersicherheitsstandards und Zertifizierungsschemata', 'offen', NULL, NULL, NULL, 1748, 18, '2026-09-22 06:33:28', NULL, NULL, NULL),
(132, 3, 1749, 'NIS2', 'Kap. IV – Risikomanagement', 'Art. 23 Abs. 1', 'Meldepflicht erheblicher Sicherheitsvorfälle', 'offen', NULL, NULL, NULL, 1749, 18, '2026-09-22 06:33:28', NULL, NULL, NULL),
(133, 3, 1750, 'NIS2', 'Kap. IV – Risikomanagement', 'Art. 23 Abs. 3', 'Kriterien für einen erheblichen Sicherheitsvorfall', 'offen', NULL, NULL, NULL, 1750, 18, '2026-09-22 06:33:28', NULL, NULL, NULL),
(134, 3, 1751, 'NIS2', 'Kap. IV – Risikomanagement', 'Art. 23 Abs. 4-5', 'Meldeprozess und Kommunikationspflichten', 'offen', NULL, NULL, NULL, 1751, 18, '2026-09-22 06:33:28', NULL, NULL, NULL),
(135, 3, 1752, 'NIS2', 'Kap. IV – Risikomanagement', 'Art. 24', 'Nutzung europäischer Cybersicherheitszertifizierungsschemata', 'offen', NULL, NULL, NULL, 1752, 18, '2026-09-22 06:33:28', NULL, NULL, NULL),
(136, 3, 1753, 'NIS2', 'Kap. IV – Risikomanagement', 'Art. 25', 'Standardisierung der Cybersicherheitsmaßnahmen', 'offen', NULL, NULL, NULL, 1753, 18, '2026-09-22 06:33:28', NULL, NULL, NULL),
(137, 3, 1754, 'NIS2', 'Kap. V – Aufsicht und Durchsetzung', 'Art. 30', 'Aufsichtsmaßnahmen und Informationspflichten gegenüber Behörden', 'offen', NULL, NULL, NULL, 1754, 18, '2026-09-22 06:33:28', NULL, NULL, NULL),
(138, 3, 1755, 'NIS2', 'Kap. V – Aufsicht und Durchsetzung', 'Art. 32-33', 'Aufsichtsmaßnahmen für wesentliche und wichtige Einrichtungen', 'offen', NULL, NULL, NULL, 1755, 18, '2026-09-22 06:33:28', NULL, NULL, NULL),
(139, 3, 1756, 'NIS2', 'Kap. V – Aufsicht und Durchsetzung', 'Art. 34', 'Sanktionen und Bußgeldrahmen', 'offen', NULL, NULL, NULL, 1756, 18, '2026-09-22 06:33:28', NULL, NULL, NULL),
