(191, 5, 540, 'ISO/IEC 27001:2022', 'Kapitel 5', '5.2', 'Informationssicherheitspolitik', 'offen', NULL, NULL, NULL, 540, 29, '2026-09-22 10:58:43', NULL, NULL, NULL),
(192, 5, 541, 'ISO/IEC 27001:2022', 'Kapitel 5', '5.3', 'Rollen und Verantwortlichkeiten', 'offen', NULL, NULL, NULL, 541, 29, '2026-09-22 10:58:43', NULL, NULL, NULL),
(193, 5, 542, 'ISO/IEC 27001:2022', 'Kapitel 6', '6.1', 'Umgang mit Risiken und Chancen', 'offen', NULL, NULL, NULL, 542, 29, '2026-09-22 10:58:43', NULL, NULL, NULL),
(194, 5, 543, 'ISO/IEC 27001:2022', 'Kapitel 6', '6.1.1', 'Risikobewertung', 'offen', NULL, NULL, NULL, 543, 29, '2026-09-22 10:58:43', NULL, NULL, NULL),
(195, 5, 544, 'ISO/IEC 27001:2022', 'Kapitel 6', '6.1.2', 'Risikobehandlung', 'offen', NULL, NULL, NULL, 544, 29, '2026-09-22 10:58:43', NULL, NULL, NULL),
(196, 5, 545, 'ISO/IEC 27001:2022', 'Kapitel 6', '6.2', 'Informationssicherheitsziele', 'offen', NULL, NULL, NULL, 545, 29, '2026-09-22 10:58:43', NULL, NULL, NULL),
(197, 5, 546, 'ISO/IEC 27001:2022', 'Kapitel 7', '7.1', 'Ressourcen', 'offen', NULL, NULL, NULL, 546, 29, '2026-09-22 10:58:43', NULL, NULL, NULL),
(198, 5, 547, 'ISO/IEC 27001:2022', 'Kapitel 7', '7.2', 'Kompetenz', 'offen', NULL, NULL, NULL, 547, 29, '2026-09-22 10:58:43', NULL, NULL, NULL),
(199, 5, 548, 'ISO/IEC 27001:2022', 'Kapitel 7', '7.3', 'Bewusstsein', 'offen', NULL, NULL, NULL, 548, 29, '2026-09-22 10:58:43', NULL, NULL, NULL),
(200, 5, 549, 'ISO/IEC 27001:2022', 'Kapitel 7', '7.4', 'Kommunikation', 'offen', NULL, NULL, NULL, 549, 29, '2026-09-22 10:58:43', NULL, NULL, NULL),
(201, 5, 550, 'ISO/IEC 27001:2022', 'Kapitel 7', '7.5', 'Dokumentierte Informationen', 'offen', NULL, NULL, NULL, 550, 29, '2026-09-22 10:58:43', NULL, NULL, NULL),
(202, 5, 551, 'ISO/IEC 27001:2022', 'Kapitel 8', '8.1', 'Betriebliche Planung und Steuerung', 'offen', NULL, NULL, NULL, 551, 29, '2026-09-22 10:58:43', NULL, NULL, NULL),
(203, 5, 552, 'ISO/IEC 27001:2022', 'Kapitel 9', '9.1', 'Überwachung, Messung und Analyse', 'offen', NULL, NULL, NULL, 552, 29, '2026-09-22 10:58:43', NULL, NULL, NULL),
(204, 5, 553, 'ISO/IEC 27001:2022', 'Kapitel 9', '9.2', 'Internes Audit', 'offen', NULL, NULL, NULL, 553, 29, '2026-09-22 10:58:43', NULL, NULL, NULL),
(205, 5, 554, 'ISO/IEC 27001:2022', 'Kapitel 9', '9.3', 'Managementbewertung', 'offen', NULL, NULL, NULL, 554, 29, '2026-09-22 10:58:43', NULL, NULL, NULL),
(206, 5, 555, 'ISO/IEC 27001:2022', 'Kapitel 10', '10.1', 'Nichtkonformität und Korrekturmaßnahmen', 'offen', NULL, NULL, NULL, 555, 29, '2026-09-22 10:58:43', NULL, NULL, NULL),
(207, 5, 556, 'ISO/IEC 27001:2022', 'Kapitel 10', '10.2', 'Kontinuierliche Verbesserung', 'offen', NULL, NULL, NULL, 556, 29, '2026-09-22 10:58:43', NULL, NULL, NULL),
(208, 5, 557, 'ISO/IEC 27001:2022', 'Anhang A', 'A.5.1', 'Richtlinien zur Informationssicherheit', 'offen', NULL, NULL, NULL, 557, 29, '2026-09-22 10:58:43', 29, '2026-09-22 11:00:17', 'Gefordert ist eine dokumentierte Informationssicherheitsleitlinie, die Grundsätze, Ziele und Verbindlichkeit festlegt. Bei einem Kleinunternehmen mit unter 10 Mitarbeitern genügt ein schlankes, ein- bis zweiseitiges Dokument, das von der Geschäftsführung freigegeben ist. Prüfer achten darauf, ob die Leitlinie allen Mitarbeitern bekannt ist und ob sie aktuelle Themen wie Cloud-Nutzung oder SaaS-Entwicklung adressiert. Typische Nachweise sind das unterschriebene Dokument, Verteilnachweise (z. B. E-Mail, Intranet) und Bestätigung der Kenntnisnahme durch Mitarbeiter.'),
(209, 5, 558, 'ISO/IEC 27001:2022', 'Anhang A', 'A.5.2', 'Überprüfung der Sicherheitsvorgaben', 'offen', NULL, NULL, NULL, 558, 29, '2026-09-22 10:58:43', 29, '2026-09-22 11:00:17', 'Die Sicherheitsrichtlinien müssen regelmäßig auf Aktualität und Wirksamkeit geprüft werden – bei einem kleinen Softwareunternehmen reicht oft ein jährlicher Review durch die Geschäftsführung. Prüfer fragen nach dem letzten Überprüfungsdatum, ausgelösten Änderungen und ob externe Faktoren wie neue Bedrohungen oder Kundenanforderungen berücksichtigt wurden. Nachweise sind datierte Reviewprotokolle, Versionsstände der Dokumente und dokumentierte Anpassungen nach relevanten Ereignissen.'),
(210, 5, 559, 'ISO/IEC 27001:2022', 'Anhang A', 'A.5.3', 'Rollen und Verantwortlichkeiten', 'offen', NULL, NULL, NULL, 559, 29, '2026-09-22 10:58:43', 29, '2026-09-22 11:00:17', 'Aufgaben, Verantwortlichkeiten und Befugnisse für Informationssicherheit müssen klar zugewiesen und kommuniziert sein. In einem Kleinbetrieb kann dies pragmatisch über Stellenbeschreibungen, eine einfache RACI-Matrix oder einen Organigramm-Anhang erfolgen. Prüfer achten darauf, ob jeder weiß, wer für Sicherheitsthemen zuständig ist und ob Stellvertretungen geregelt sind. Nachweise sind dokumentierte Rollenzuweisungen, Arbeitsverträge mit Sicherheitsaufgaben oder Protokolle, die die Kommunikation belegen.'),
(211, 5, 560, 'ISO/IEC 27001:2022', 'Anhang A', 'A.5.4', 'Leitungsverantwortung', 'offen', NULL, NULL, NULL, 560, 29, '2026-09-22 10:58:43', 29, '2026-09-22 11:00:17', 'Die Geschäftsführung muss Informationssicherheit aktiv unterstützen und ausreichende Ressourcen bereitstellen. Bei einer kleinen GmbH zeigt sich dies durch persönliches Engagement, Budgetfreigaben für Sicherheitsmaßnahmen und Teilnahme an Reviews. Prüfer fragen, wie die Leitung ihr Commitment demonstriert und ob Zeit und Mittel für ISMS-Aufgaben eingeplant sind. Nachweise sind Management-Review-Protokolle, freigegebene Budgets, Schulungsteilnahmen der Führung und dokumentierte Entscheidungen zu Sicherheitsthemen.'),
(212, 5, 561, 'ISO/IEC 27001:2022', 'Anhang A', 'A.5.5', 'Kontakt zu Behörden', 'offen', NULL, NULL, NULL, 561, 29, '2026-09-22 10:58:43', 29, '2026-09-22 11:00:17', 'Relevante Behördenkontakte für Sicherheitsvorfälle müssen identifiziert und dokumentiert sein – für ein IT-Unternehmen in Baden-Württemberg etwa BSI, LKA Cybercrime, Datenschutzaufsicht und ggf. CERT-Bund. Prüfer fragen, ob Kontaktdaten aktuell vorliegen und wann diese zuletzt geprüft wurden. Nachweise sind eine gepflegte Kontaktliste mit Ansprechpartnern, dokumentierte Meldewege und ggf. Nachweise über bisherige Abstimmungen oder Meldungen.'),
(213, 5, 562, 'ISO/IEC 27001:2022', 'Anhang A', 'A.5.6', 'Kontakt zu Interessengruppen', 'offen', NULL, NULL, NULL, 562, 29, '2026-09-22 10:58:43', 29, '2026-09-22 11:00:17', 'Der Austausch mit externen Interessengruppen zur Informationssicherheit soll geplant sein. Für ein SaaS-Unternehmen sind das z. B. Branchenverbände wie Bitkom, ISACA-Chapter, Security-Communities oder Kundengruppen mit Sicherheitsanforderungen. Prüfer achten darauf, ob relevante Gruppen identifiziert sind und wie der Informationsaustausch erfolgt. Nachweise sind eine Liste relevanter Stakeholder, Mitgliedschaften, Teilnahmenachweise an Arbeitskreisen oder dokumentierter Informationsaustausch.'),
(214, 5, 563, 'ISO/IEC 27001:2022', 'Anhang A', 'A.5.7', 'Threat Intelligence', 'offen', NULL, NULL, NULL, 563, 29, '2026-09-22 10:58:43', 29, '2026-09-22 11:00:17', 'Bedrohungsinformationen müssen systematisch gesammelt und in Schutzmaßnahmen einbezogen werden. Für einen kleinen Softwareentwickler genügt das regelmäßige Auswerten von BSI-Warnungen, CVE-Feeds oder branchenspezifischen Security-Newslettern. Prüfer fragen, welche Quellen genutzt werden, wie Informationen bewertet und welche Maßnahmen daraus abgeleitet wurden. Nachweise sind abonnierte Quellen, dokumentierte Auswertungen und nachvollziehbare Reaktionen auf relevante Bedrohungshinweise.'),
(215, 5, 564, 'ISO/IEC 27001:2022', 'Anhang A', 'A.5.8', 'Informationssicherheit im Projektmanagement', 'offen', NULL, NULL, NULL, 564, 29, '2026-09-22 10:58:43', 29, '2026-09-22 11:00:17', 'Sicherheitsanforderungen müssen in Projekte integriert werden – von Planung bis Go-Live. Bei der Entwicklung einer ISMS-Software bedeutet das Security by Design, Threat Modeling und Sicherheitstests vor Release. Prüfer achten darauf, ob Projekte eine Sicherheitsbetrachtung durchlaufen und ob dies dokumentiert ist. Nachweise sind Projektchecklisten mit Sicherheitskriterien, Risikoanalysen für Projekte, Testprotokolle und Freigabedokumente mit Sicherheitsabnahme.'),
(216, 5, 565, 'ISO/IEC 27001:2022', 'Anhang A', 'A.5.9', 'Asset-Inventar', 'offen', NULL, NULL, NULL, 565, 29, '2026-09-22 10:58:43', 29, '2026-09-22 11:00:17', 'Alle Informationswerte müssen inventarisiert sein, sodass Zuständigkeiten und Schutzbedarf erkennbar sind. Für ein kleines Softwareunternehmen umfasst dies Quellcode, Kundendaten, Server, Entwicklungsumgebungen und Cloud-Ressourcen. Prüfer fragen, ob das Inventar vollständig, aktuell und mit Eigentümern versehen ist. Nachweise sind eine Asset-Liste (z. B. Excel, CMDB), dokumentierte Schutzbedarfsfeststellungen und ein nachvollziehbarer Aktualisierungsprozess.'),
(217, 5, 566, 'ISO/IEC 27001:2022', 'Anhang A', 'A.5.10', 'Erlaubte Nutzung von Assets', 'offen', NULL, NULL, NULL, 566, 29, '2026-09-22 10:58:43', 29, '2026-09-22 11:00:17', 'Für die Nutzung von Informationswerten müssen klare Regeln existieren, um Missbrauch und Datenabfluss zu verhindern. Bei einem SaaS-Anbieter betrifft dies z. B. Umgang mit Quellcode, Kundendaten, Testdaten und Cloud-Zugängen. Prüfer achten darauf, ob Nutzungsregeln dokumentiert, kommuniziert und praktisch umsetzbar sind. Nachweise sind Nutzungsrichtlinien, Arbeitsanweisungen, Bestätigungen der Mitarbeiter und ggf. technische Einschränkungen wie Zugriffskontrollen.'),
(218, 5, 567, 'ISO/IEC 27001:2022', 'Anhang A', 'A.5.11', 'Rückgabe von Assets', 'offen', NULL, NULL, NULL, 567, 29, '2026-09-22 10:58:43', NULL, NULL, NULL),
(219, 5, 568, 'ISO/IEC 27001:2022', 'Anhang A', 'A.5.12', 'Klassifizierung von Informationen', 'offen', NULL, NULL, NULL, 568, 29, '2026-09-22 10:58:43', NULL, NULL, NULL),
(220, 5, 569, 'ISO/IEC 27001:2022', 'Anhang A', 'A.5.13', 'Kennzeichnung von Informationen', 'offen', NULL, NULL, NULL, 569, 29, '2026-09-22 10:58:43', NULL, NULL, NULL),
