(287, 5, 636, 'ISO/IEC 27001:2022', 'Anhang A', 'A.8.21', 'Netzwerkdienste', 'offen', NULL, NULL, NULL, 636, 29, '2026-09-22 10:58:43', NULL, NULL, NULL),
(288, 5, 637, 'ISO/IEC 27001:2022', 'Anhang A', 'A.8.22', 'Trennung von Netzwerken', 'offen', NULL, NULL, NULL, 637, 29, '2026-09-22 10:58:43', NULL, NULL, NULL),
(289, 5, 638, 'ISO/IEC 27001:2022', 'Anhang A', 'A.8.23', 'Webfilterung', 'offen', NULL, NULL, NULL, 638, 29, '2026-09-22 10:58:43', NULL, NULL, NULL),
(290, 5, 639, 'ISO/IEC 27001:2022', 'Anhang A', 'A.8.24', 'Kryptografische Verfahren', 'offen', NULL, NULL, NULL, 639, 29, '2026-09-22 10:58:43', NULL, NULL, NULL),
(291, 5, 640, 'ISO/IEC 27001:2022', 'Anhang A', 'A.8.25', 'Schlüsselmanagement', 'offen', NULL, NULL, NULL, 640, 29, '2026-09-22 10:58:43', NULL, NULL, NULL),
(292, 5, 641, 'ISO/IEC 27001:2022', 'Anhang A', 'A.8.26', 'Sichere Entwicklung', 'offen', NULL, NULL, NULL, 641, 29, '2026-09-22 10:58:43', 29, '2026-09-22 11:02:34', 'Die Anforderung verlangt, dass Sicherheitsaspekte systematisch in den Softwareentwicklungsprozess integriert werden – von der Anforderungsanalyse bis zur Auslieferung. Für ein kleines Softwareunternehmen reicht oft eine dokumentierte Checkliste mit Sicherheitsanforderungen je Ticket oder User Story sowie klare Verantwortlichkeiten im Team. Prüfer achten darauf, ob Sicherheitsanforderungen nachvollziehbar erfasst und bei Abnahme geprüft werden. Typische Nachweise sind Entwicklungsrichtlinien, Ticket-System mit Security-Kriterien, Definition-of-Done und Freigabeprotokolle. Bei einer SaaS-Lösung ist besonders relevant, wie Mandantentrennung und Datenschutz bereits in Anforderungen einfließen.'),
(293, 5, 642, 'ISO/IEC 27001:2022', 'Anhang A', 'A.8.27', 'Sichere Architektur', 'offen', NULL, NULL, NULL, 642, 29, '2026-09-22 10:58:43', 29, '2026-09-22 11:02:34', 'Hier wird geprüft, ob Systeme nach anerkannten Sicherheitsprinzipien entworfen werden: Trennung von Komponenten, minimale Rechte, Defense-in-Depth. Für eine ISMS-Software bedeutet das etwa strikte Mandantentrennung, API-Gateway-Konzepte und Netzwerksegmentierung. Der Prüfer fragt nach Architekturdiagrammen, Designentscheidungen und deren Sicherheitsbegründung. Typische Lücken sind fehlende Dokumentation oder monolithische Strukturen ohne Trennungskonzept. Nachweise umfassen Architekturskizzen, Threat-Modeling-Ergebnisse und Protokolle von Design-Reviews, auch wenn diese bei einem Kleinunternehmen pragmatisch ausfallen dürfen.'),
(294, 5, 643, 'ISO/IEC 27001:2022', 'Anhang A', 'A.8.28', 'Sicheres Coding', 'offen', NULL, NULL, NULL, 643, 29, '2026-09-22 10:58:43', 29, '2026-09-22 11:02:34', 'Entwicklungsrichtlinien sollen typische Programmierfehler wie Injection, XSS oder unsichere Authentifizierung vermeiden. Für ein kleines Entwicklerteam genügt oft ein verbindlicher Coding-Standard mit OWASP-Bezug plus systematische Code-Reviews. Der Prüfer fragt, welche Standards gelten, wie sie vermittelt werden und ob Reviews stattfinden. Typische Lücken sind fehlende oder veraltete Richtlinien und ausbleibende Vier-Augen-Kontrolle. Nachweise sind Coding-Guidelines, Review-Protokolle oder Merge-Request-Kommentare, IDE-Linter-Konfigurationen und ggf. SAST-Tool-Berichte.'),
(295, 5, 644, 'ISO/IEC 27001:2022', 'Anhang A', 'A.8.29', 'Sicherheitstests', 'offen', NULL, NULL, NULL, 644, 29, '2026-09-22 10:58:43', 29, '2026-09-22 11:02:34', 'Vor Produktivsetzung müssen gezielte Sicherheitstests geplant und durchgeführt werden, um Schwachstellen frühzeitig zu erkennen. Für ein kleines SaaS-Unternehmen sind automatisierte Scans (DAST, Dependency-Check) und manuelle Penetrationstests bei größeren Releases angemessen. Der Prüfer prüft, ob ein Testplan existiert, wann zuletzt getestet wurde und wie mit Findings umgegangen wird. Typische Lücken sind fehlende Regelmäßigkeit oder nicht behobene kritische Schwachstellen. Nachweise sind Testpläne, Scan-Reports, Pentest-Berichte und Ticket-Nachverfolgung der Befunde.'),
(296, 5, 645, 'ISO/IEC 27001:2022', 'Anhang A', 'A.8.30', 'Externe Entwicklung', 'offen', NULL, NULL, NULL, 645, 29, '2026-09-22 10:58:43', 29, '2026-09-22 11:02:34', 'Werden Entwicklungsleistungen extern vergeben, müssen Sicherheitsanforderungen vertraglich festgelegt und deren Einhaltung überwacht werden. Bei einem Kleinunternehmen betrifft das oft Freelancer oder Agenturleistungen. Der Prüfer fragt nach Vertragsklauseln zu Sicherheitsstandards, Geheimhaltung, Codequalität und Übergabeprozessen. Typische Lücken sind fehlende NDA, unklare Schnittstellenverantwortung oder kein Code-Review externer Lieferungen. Nachweise umfassen Verträge mit Sicherheitsanhang, Abnahmeprotokolle, dokumentierte Schnittstellendefinitionen und Review-Ergebnisse für externen Code.'),
(297, 5, 646, 'ISO/IEC 27001:2022', 'Anhang A', 'A.8.31', 'Produktionsumgebung', 'offen', NULL, NULL, NULL, 646, 29, '2026-09-22 10:58:43', 29, '2026-09-22 11:02:34', 'Produktionssysteme – hier die SaaS-Plattform – erfordern besonderen Schutz: strikter Zugriff nur für Berechtigte, kontrollierte Änderungen, Überwachung. Der Prüfer prüft, ob Produktionszugang auf wenige Personen beschränkt ist, Änderungen dokumentiert werden und Notfallzugriffe geregelt sind. Typische Lücken sind Shared-Accounts, fehlende Protokollierung oder unkontrollierte Direktzugriffe. Nachweise sind Zugriffslisten, Rollendefinitionen, Change-Logs, Monitoring-Dashboards und Protokolle von Wartungszugriffen. Bei Hosting in der Cloud ist die Konfiguration des Cloud-Providers relevant.'),
(298, 5, 647, 'ISO/IEC 27001:2022', 'Anhang A', 'A.8.32', 'Änderungsmanagement', 'offen', NULL, NULL, NULL, 647, 29, '2026-09-22 10:58:43', 29, '2026-09-22 11:02:34', 'Änderungen an Systemen und Software müssen geplant, bewertet, genehmigt und dokumentiert werden, um unkontrollierte Auswirkungen zu vermeiden. Für ein kleines Team reicht ein schlanker Prozess: Ticket anlegen, Auswirkungen prüfen, Freigabe durch zweite Person, Dokumentation im Versionskontrollsystem. Der Prüfer fragt nach dem Change-Prozess, Genehmigungsstufen und Rückrollmöglichkeiten. Typische Lücken sind undokumentierte Hotfixes oder fehlende Freigaben. Nachweise sind Change-Policy, Tickethistorie, Git-Commits mit Merge-Approvals und Release-Notes.'),
(299, 5, 648, 'ISO/IEC 27001:2022', 'Anhang A', 'A.8.33', 'Testdaten', 'offen', NULL, NULL, NULL, 648, 29, '2026-09-22 10:58:43', 29, '2026-09-22 11:02:34', 'Testdaten dürfen keine echten personenbezogenen oder vertraulichen Produktionsdaten enthalten, sofern sie nicht anonymisiert oder maskiert sind. Bei einer ISMS-Software mit Kundendaten ist das besonders kritisch. Der Prüfer fragt, woher Testdaten stammen, ob Produktionsdaten kopiert werden und welche Schutzmaßnahmen greifen. Typische Lücken sind ungeschützte Datenbank-Dumps in Testumgebungen oder fehlende Anonymisierungsroutinen. Nachweise sind Richtlinien zur Testdatenverwendung, Anonymisierungsskripte, Freigaben für Testdaten und Protokolle der Datenbeschaffung.'),
(300, 5, 649, 'ISO/IEC 27001:2022', 'Anhang A', 'A.8.34', 'Trennung Test/Produktion', 'offen', NULL, NULL, NULL, 649, 29, '2026-09-22 10:58:43', 29, '2026-09-22 11:01:21', 'Die Anforderung verlangt eine klare Trennung zwischen Test- und Produktivumgebungen, um Risiken durch Datenabfluss, versehentliche Änderungen oder Fehlbedienung zu minimieren. Für einen kleinen Softwareanbieter mit SaaS-Produkt ist dies besonders relevant, da Kundendaten in der Produktivumgebung geschützt werden müssen und Entwicklungsfehler nicht live wirksam werden dürfen. Bei der Prüfung wird geachtet auf: getrennte Infrastruktur oder zumindest logische Separation, unterschiedliche Zugriffsrechte, Verwendung anonymisierter oder synthetischer Testdaten statt echter Kundendaten. Typische Nachweise sind Netzwerk- oder Systemarchitektur-Dokumentation, Konfigurationsnachweise der Cloud-Umgebung, Berechtigungslisten sowie Entwicklerinterviews zur tatsächlichen Arbeitsweise bei Deployments und Tests.'),
(301, 6, 557, 'ISO/IEC 27001:2022', 'Anhang A', 'A.5.1', 'Richtlinien zur Informationssicherheit', 'offen', NULL, NULL, NULL, 557, 29, '2026-09-22 15:58:55', 29, '2026-09-22 16:05:10', 'Existiert eine schriftliche Informationssicherheitsrichtlinie, und wer hat diese freigegeben?\r\nWelche Kernthemen deckt Ihre Richtlinie ab, z. B. Schutzziele, Geltungsbereich, Verantwortlichkeiten?\r\nWie stellen Sie sicher, dass alle Mitarbeitenden die Richtlinie kennen und verstehen, z. B. Onboarding, Intranet, Unterschrift?\r\nWann wurde die Richtlinie zuletzt aktualisiert, und was war der Anlass?'),
(302, 6, 558, 'ISO/IEC 27001:2022', 'Anhang A', 'A.5.2', 'Überprüfung der Sicherheitsvorgaben', 'offen', NULL, NULL, NULL, 558, 29, '2026-09-22 15:58:55', 29, '2026-09-22 16:05:10', 'In welchem Turnus überprüfen Sie Ihre Sicherheitsrichtlinien auf Aktualität und Angemessenheit?\r\nWer ist für die Bewertung und Freigabe von Änderungen verantwortlich?\r\nWelche Auslöser führen zu einer außerplanmäßigen Überprüfung, z. B. neue Bedrohungen, Vorfälle, Gesetzesänderungen?\r\nWie dokumentieren Sie durchgeführte Reviews und deren Ergebnisse, z. B. Protokolle, Versionierung?'),
(303, 6, 559, 'ISO/IEC 27001:2022', 'Anhang A', 'A.5.3', 'Rollen und Verantwortlichkeiten', 'offen', NULL, NULL, NULL, 559, 29, '2026-09-22 15:58:55', 29, '2026-09-22 16:05:10', 'Wie sind Rollen und Verantwortlichkeiten für Informationssicherheit in Ihrem Kleinteam festgelegt, z. B. Organigramm, Stellenbeschreibung, RACI-Matrix?\r\nWer übernimmt die Funktion eines Informationssicherheitsbeauftragten oder vergleichbare Aufgaben?\r\nWie kommunizieren Sie diese Zuständigkeiten an alle Mitarbeitenden?\r\nSind Vertretungsregelungen definiert, falls Verantwortliche ausfallen?'),
(304, 6, 560, 'ISO/IEC 27001:2022', 'Anhang A', 'A.5.4', 'Leitungsverantwortung', 'offen', NULL, NULL, NULL, 560, 29, '2026-09-22 15:58:55', 29, '2026-09-22 16:05:10', 'Wie zeigt die Geschäftsführung ihr aktives Engagement für Informationssicherheit, z. B. Budget, Teilnahme an Reviews, Unterschrift unter Richtlinien?\r\nWelche Ressourcen – zeitlich, personell, finanziell – stehen für Sicherheitsmaßnahmen zur Verfügung?\r\nWie wird Informationssicherheit in strategische Entscheidungen einbezogen, etwa bei der SaaS-Produktentwicklung?'),
(305, 6, 561, 'ISO/IEC 27001:2022', 'Anhang A', 'A.5.5', 'Kontakt zu Behörden', 'offen', NULL, NULL, NULL, 561, 29, '2026-09-22 15:58:55', 29, '2026-09-22 16:05:10', 'Welche Behörden sind für Sie im Sicherheitskontext relevant, z. B. BSI, LfDI Baden-Württemberg, CERT-Bund?\r\nWo sind Kontaktdaten und Ansprechpartner dokumentiert?\r\nIn welchen Fällen würden Sie Kontakt aufnehmen, z. B. Meldepflichten nach DSGVO, NIS2-Relevanz prüfen?\r\nHaben Sie bereits Erfahrungen mit behördlicher Kommunikation gesammelt?'),
(306, 6, 562, 'ISO/IEC 27001:2022', 'Anhang A', 'A.5.6', 'Kontakt zu Interessengruppen', 'offen', NULL, NULL, NULL, 562, 29, '2026-09-22 15:58:55', 29, '2026-09-22 16:05:10', 'Mit welchen externen Interessengruppen tauschen Sie sich zu Sicherheitsthemen aus, z. B. Branchenverbände, ISACA, Bitkom-Arbeitskreise?\r\nWie ist dieser Austausch organisiert, z. B. Abonnements, Mitgliedschaften, regelmäßige Meetings?\r\nWelchen Nutzen ziehen Sie daraus für Ihre Sicherheitsmaßnahmen?\r\nWer im Unternehmen pflegt diese Kontakte?'),
(307, 6, 563, 'ISO/IEC 27001:2022', 'Anhang A', 'A.5.7', 'Threat Intelligence', 'offen', NULL, NULL, NULL, 563, 29, '2026-09-22 15:58:55', 29, '2026-09-22 16:05:10', 'Wie informieren Sie sich über aktuelle Bedrohungen und Schwachstellen, z. B. BSI-Warnungen, CVE-Feeds, Security-Newsletter?\r\nWer wertet diese Informationen aus und entscheidet über Maßnahmen?\r\nWie fließen gewonnene Erkenntnisse in Ihre Schutzmaßnahmen oder Ihr Risikomanagement ein?\r\nKönnen Sie ein Beispiel nennen, bei dem Threat Intelligence zu einer konkreten Maßnahme geführt hat?'),
(308, 6, 564, 'ISO/IEC 27001:2022', 'Anhang A', 'A.5.8', 'Informationssicherheit im Projektmanagement', 'offen', NULL, NULL, NULL, 564, 29, '2026-09-22 15:58:55', 29, '2026-09-22 16:05:10', 'Wie stellen Sie sicher, dass Sicherheitsanforderungen von Beginn an in Ihre Softwareprojekte einfließen, z. B. Security-Checklisten, Anforderungskataloge?\r\nWelche Sicherheitsaspekte prüfen Sie bei der Entwicklung Ihrer ISMS-Software, z. B. sichere Codierung, Penetrationstests?\r\nWie wird Sicherheit bei der Übergabe in den Betrieb oder bei Releases berücksichtigt?\r\nWer trägt die Verantwortung für Sicherheit im Projektverlauf?'),
(309, 6, 565, 'ISO/IEC 27001:2022', 'Anhang A', 'A.5.9', 'Asset-Inventar', 'offen', NULL, NULL, NULL, 565, 29, '2026-09-22 15:58:55', 29, '2026-09-22 16:05:10', 'Führen Sie ein Inventar Ihrer Informationswerte, z. B. Systeme, Daten, Softwarelizenzen, und wo ist dieses dokumentiert?\r\nWelche Angaben erfassen Sie pro Asset, z. B. Eigentümer, Standort, Schutzbedarf?\r\nWie halten Sie das Inventar aktuell, insbesondere bei neuen Entwicklungen für Ihr SaaS-Produkt?\r\nWer ist für die Pflege des Asset-Inventars verantwortlich?'),
(310, 6, 566, 'ISO/IEC 27001:2022', 'Anhang A', 'A.5.10', 'Erlaubte Nutzung von Assets', 'offen', NULL, NULL, NULL, 566, 29, '2026-09-22 15:58:55', 29, '2026-09-22 16:05:10', 'Welche Regeln gelten für die Nutzung von IT-Systemen, Daten und Software, z. B. Nutzungsrichtlinie, Betriebsvereinbarung?\r\nWie ist die private Nutzung von Firmengeräten geregelt?\r\nWelche Vorkehrungen treffen Sie gegen Datenabfluss, z. B. bei Kundendaten in der SaaS-Lösung?\r\nWie werden Mitarbeitende über erlaubte und untersagte Nutzung informiert?'),
(311, 6, 567, 'ISO/IEC 27001:2022', 'Anhang A', 'A.5.11', 'Rückgabe von Assets', 'offen', NULL, NULL, NULL, 567, 29, '2026-09-22 15:58:55', 29, '2026-09-22 16:05:10', 'Wie stellen Sie sicher, dass beim Austritt eines Mitarbeitenden alle Assets zurückgegeben werden, z. B. Checkliste, Übergabeprotokoll?\r\nWelche Zugänge und Berechtigungen werden bei Austritt oder Rollenwechsel entzogen, und wer veranlasst dies?\r\nWie schnell erfolgt die Sperrung von Accounts nach Vertragsende?\r\nGibt es dokumentierte Fälle, in denen dieses Verfahren angewendet wurde?');
INSERT INTO `aud_pruefpunkte` (`id`, `audit_id`, `norm_id`, `norm`, `kapitel`, `nummer`, `titel`, `bewertung`, `feststellung`, `nachweis`, `abweichung_id`, `sortierung`, `Ersteller`, `erstellt`, `Aenderer`, `geaendert`, `beschreibung`) VALUES
(312, 6, 568, 'ISO/IEC 27001:2022', 'Anhang A', 'A.5.12', 'Klassifizierung von Informationen', 'offen', NULL, NULL, NULL, 568, 29, '2026-09-22 15:58:55', 29, '2026-09-22 16:05:10', 'Nach welchem Schema klassifizieren Sie Ihre Informationen, z. B. öffentlich, intern, vertraulich, streng vertraulich?\r\nWelche Kriterien nutzen Sie für die Einstufung, z. B. Geschäftsgeheimnis, Kundendaten, personenbezogene Daten?\r\nWo ist das Klassifizierungsschema dokumentiert, und wer entscheidet über die Einstufung?\r\nWie leiten Sie aus der Klassifizierung konkrete Schutzmaßnahmen ab?'),
(313, 6, 569, 'ISO/IEC 27001:2022', 'Anhang A', 'A.5.13', 'Kennzeichnung von Informationen', 'offen', NULL, NULL, NULL, 569, 29, '2026-09-22 15:58:55', 29, '2026-09-22 16:05:10', 'Wie kennzeichnen Sie klassifizierte Informationen, z. B. Wasserzeichen, Header, Dateinamenskonvention, Labels in Tools?\r\nGilt die Kennzeichnung sowohl für digitale als auch für physische Dokumente?\r\nWie stellen Sie sicher, dass Mitarbeitende die Kennzeichnung verstehen und beachten?\r\nWas passiert, wenn ein Dokument nicht gekennzeichnet ist?'),
(314, 6, 570, 'ISO/IEC 27001:2022', 'Anhang A', 'A.5.14', 'Informationsübertragung', 'offen', NULL, NULL, NULL, 570, 29, '2026-09-22 15:58:55', 29, '2026-09-22 16:05:10', 'Welche Regeln gelten für die Übertragung vertraulicher Informationen, z. B. Verschlüsselungspflicht, zugelassene Kanäle?\r\nWie übermitteln Sie sensible Daten an Kunden oder Partner, z. B. verschlüsselte E-Mail, SFTP, sichere Portale?\r\nWer gibt die Weitergabe vertraulicher Informationen frei?\r\nWie dokumentieren Sie die Übertragung, z. B. Protokolle, Empfangsbestätigungen?'),
(315, 6, 571, 'ISO/IEC 27001:2022', 'Anhang A', 'A.5.15', 'Zugriffskontrolle', 'offen', NULL, NULL, NULL, 571, 29, '2026-09-22 15:58:55', 29, '2026-09-22 16:05:10', 'Nach welchen Prinzipien vergeben Sie Zugriffsrechte, z. B. Need-to-know, Least Privilege, rollenbasiert?\r\nWie dokumentieren Sie, wer auf welche Systeme und Daten zugreifen darf, z. B. Berechtigungsmatrix, IAM-Tool?\r\nIn welchem Turnus überprüfen Sie bestehende Berechtigungen?\r\nWie gehen Sie mit privilegierten Zugängen um, z. B. Administratorrechte?'),
(316, 6, 572, 'ISO/IEC 27001:2022', 'Anhang A', 'A.5.16', 'Identitätsmanagement', 'offen', NULL, NULL, NULL, 572, 29, '2026-09-22 15:58:55', 29, '2026-09-22 16:05:10', 'Wie legen Sie neue Benutzerkonten an, und welche Freigabeschritte sind erforderlich?\r\nWie werden Änderungen an Identitäten dokumentiert, z. B. Namensänderung, Abteilungswechsel?\r\nWie stellen Sie sicher, dass inaktive Konten zeitnah deaktiviert werden?\r\nWelche Systeme nutzen Sie für die Identitätsverwaltung, z. B. zentrales AD, Cloud-IdP?'),
(317, 6, 573, 'ISO/IEC 27001:2022', 'Anhang A', 'A.5.17', 'Authentifizierungsinformationen', 'offen', NULL, NULL, NULL, 573, 29, '2026-09-22 15:58:55', 29, '2026-09-22 16:05:10', 'Welche Passwortrichtlinien gelten, z. B. Mindestlänge, Komplexität, Ablaufdauer?\r\nWie werden Passwörter und andere Authentifizierungsdaten sicher gespeichert, z. B. Passwort-Manager, Hashing?\r\nNutzen Sie Multi-Faktor-Authentifizierung, insbesondere für kritische Systeme oder Ihre SaaS-Plattform?\r\nWie stellen Sie Passwörter bei Ersteinrichtung oder Zurücksetzen sicher bereit?'),
(318, 6, 574, 'ISO/IEC 27001:2022', 'Anhang A', 'A.5.18', 'Berechtigungsverwaltung', 'offen', NULL, NULL, NULL, 574, 29, '2026-09-22 15:58:55', 29, '2026-09-22 16:05:10', 'Wie wird die Vergabe von Zugriffsrechten beantragt und freigegeben, z. B. Ticketsystem, schriftlicher Antrag?\r\nWer genehmigt Berechtigungen, und wie wird dies dokumentiert?\r\nIn welchem Rhythmus führen Sie Rezertifizierungen durch, und wie dokumentieren Sie diese?\r\nWie schnell werden Rechte entzogen, wenn sie nicht mehr benötigt werden?'),
(319, 6, 575, 'ISO/IEC 27001:2022', 'Anhang A', 'A.5.19', 'Informationssicherheit bei Lieferanten', 'offen', NULL, NULL, NULL, 575, 29, '2026-09-22 15:58:55', 29, '2026-09-22 16:05:10', 'Welche Lieferanten haben Zugang zu Ihren Informationen oder Systemen, z. B. Hosting-Provider, Cloud-Dienste, Freelancer?\r\nWie bewerten Sie die Informationssicherheit Ihrer Lieferanten vor Vertragsabschluss, z. B. Fragebögen, Zertifikate, Audits?\r\nWelche Risiken sehen Sie in Ihrer Lieferkette, insbesondere für Ihre SaaS-Plattform?\r\nWie überwachen Sie die Sicherheitsleistung Ihrer Lieferanten laufend?'),
(320, 6, 576, 'ISO/IEC 27001:2022', 'Anhang A', 'A.5.20', 'Sicherheitsanforderungen an Lieferanten', 'offen', NULL, NULL, NULL, 576, 29, '2026-09-22 15:58:55', 29, '2026-09-22 16:05:10', 'Welche Sicherheitsanforderungen vereinbaren Sie vertraglich mit Lieferanten, z. B. Vertraulichkeitsklauseln, AVV, SLA zur Sicherheit?\r\nWie stellen Sie sicher, dass Anforderungen dem Risiko und Schutzbedarf entsprechen?\r\nWelche Nachweise fordern Sie von Lieferanten, z. B. ISO-27001-Zertifikat, SOC-2-Report, Pentestberichte?\r\nWie gehen Sie vor, wenn ein Lieferant die Anforderungen nicht erfüllt?'),
(321, 6, 577, 'ISO/IEC 27001:2022', 'Anhang A', 'A.5.21', 'Lieferantenüberwachung', 'offen', NULL, NULL, NULL, 577, 29, '2026-09-22 15:58:55', 29, '2026-09-22 16:05:10', 'Welche Lieferanten mit Zugriff auf Ihre Systeme oder Daten haben Sie identifiziert, und wie dokumentieren Sie deren Sicherheitsanforderungen?\r\nWie überprüfen Sie regelmäßig, ob diese Lieferanten die vereinbarten Sicherheitsanforderungen einhalten, z. B. durch Zertifikatsnachweise, Selbstauskünfte oder Berichte?\r\nWelche Nachweise fordern Sie von Ihren Cloud- und Hosting-Anbietern an, z. B. SOC-2-Reports, ISO-27001-Zertifikate oder Penetrationstest-Berichte?\r\nWie gehen Sie vor, wenn ein Lieferant Sicherheitsanforderungen nicht erfüllt?'),
(322, 6, 578, 'ISO/IEC 27001:2022', 'Anhang A', 'A.5.22', 'Service-Delivery-Management', 'offen', NULL, NULL, NULL, 578, 29, '2026-09-22 15:58:55', 29, '2026-09-22 16:05:10', 'Welche Dienstleistungen haben Sie ausgelagert, die für Ihre ISMS-Software oder Kundendaten relevant sind?\r\nWie stellen Sie sicher, dass diese externen Leistungen im laufenden Betrieb Ihre Sicherheitsanforderungen einhalten, z. B. durch SLAs, regelmäßige Reviews oder definierte Ansprechpartner?\r\nWelche Dokumente belegen die Steuerung ausgelagerter Leistungen, z. B. Dienstleisterverträge mit Sicherheitsanhang, Protokolle von Service-Reviews?\r\nWer ist intern verantwortlich für die Überwachung der externen Dienstleister?'),
(323, 6, 579, 'ISO/IEC 27001:2022', 'Anhang A', 'A.5.23', 'Nutzung von Cloud-Diensten', 'offen', NULL, NULL, NULL, 579, 29, '2026-09-22 15:58:55', 29, '2026-09-22 16:05:10', 'Welche Cloud-Dienste nutzen Sie für Entwicklung, Betrieb oder Speicherung Ihrer SaaS-Lösung und Kundendaten?\r\nWie haben Sie die Sicherheitsanforderungen an diese Cloud-Dienste definiert und dokumentiert, z. B. in einer Cloud-Richtlinie oder Risikoanalyse?\r\nWelche Risikobewertung haben Sie für jeden genutzten Cloud-Dienst durchgeführt, und wo ist diese dokumentiert?\r\nWelche technischen und organisatorischen Kontrollen setzen Sie zur sicheren Cloud-Nutzung um, z. B. Verschlüsselung, Zugriffsmanagement, Standortwahl innerhalb der EU?'),
(324, 6, 580, 'ISO/IEC 27001:2022', 'Anhang A', 'A.5.24', 'Incident-Management', 'offen', NULL, NULL, NULL, 580, 29, '2026-09-22 15:58:55', 29, '2026-09-22 16:05:10', 'Wie erkennen und melden Ihre Mitarbeitenden Sicherheitsvorfälle – gibt es einen definierten Meldeweg, z. B. E-Mail-Adresse, Ticket-System oder Ansprechpartner?\r\nWelches Verfahren nutzen Sie zur Bewertung, Behandlung und Dokumentation von Vorfällen, z. B. eine Incident-Management-Richtlinie oder ein Vorfallsprotokoll?\r\nKönnen Sie ein Beispiel zeigen, wie ein vergangener Vorfall dokumentiert wurde?\r\nWer ist für die Koordination bei Sicherheitsvorfällen verantwortlich?'),
(325, 6, 581, 'ISO/IEC 27001:2022', 'Anhang A', 'A.5.25', 'Bewertung von Sicherheitsereignissen', 'offen', NULL, NULL, NULL, 581, 29, '2026-09-22 15:58:55', 29, '2026-09-22 16:05:10', 'Wie unterscheiden Sie zwischen einem Sicherheitsereignis und einem tatsächlichen Sicherheitsvorfall?\r\nNach welchen Kriterien priorisieren Sie Sicherheitsereignisse, z. B. Auswirkung auf Kundendaten, Geschäftskritikalität oder Dringlichkeit?\r\nWelche Nachweise gibt es für die Analyse und Priorisierung, z. B. Bewertungsmatrix, Ticketverläufe oder Protokolle?\r\nWie stellen Sie sicher, dass relevante Ereignisse zeitnah in den Reaktionsprozess überführt werden?'),
(326, 6, 582, 'ISO/IEC 27001:2022', 'Anhang A', 'A.5.26', 'Reaktion auf Sicherheitsvorfälle', 'offen', NULL, NULL, NULL, 582, 29, '2026-09-22 15:58:55', 29, '2026-09-22 16:05:10', 'Welche definierten Abläufe existieren zur Eindämmung und Behebung von Sicherheitsvorfällen, z. B. Notfallpläne, Checklisten oder Eskalationswege?\r\nWie stellen Sie die Wiederherstellung betroffener Systeme oder Daten sicher?\r\nWer kommuniziert intern und extern bei einem Vorfall, und nach welchen Regeln, z. B. gegenüber Kunden, Behörden oder Partnern?\r\nWelche Dokumentation belegt Ihre Reaktionsprozesse, z. B. Incident-Response-Plan, Kommunikationsvorlagen?'),
(327, 6, 583, 'ISO/IEC 27001:2022', 'Anhang A', 'A.5.27', 'Lernen aus Vorfällen', 'offen', NULL, NULL, NULL, 583, 29, '2026-09-22 15:58:55', 29, '2026-09-22 16:05:10', 'Wie werten Sie Sicherheitsvorfälle nach deren Abschluss aus, um Ursachen zu identifizieren?\r\nWelche Maßnahmen leiten Sie aus den Erkenntnissen ab, und wie dokumentieren Sie diese, z. B. in Lessons-Learned-Protokollen oder Maßnahmenlisten?\r\nKönnen Sie ein Beispiel nennen, bei dem ein Vorfall zu einer konkreten Verbesserung Ihrer Sicherheitsmaßnahmen geführt hat?\r\nWer ist verantwortlich für die Umsetzung und Nachverfolgung der Verbesserungsmaßnahmen?'),
(328, 6, 584, 'ISO/IEC 27001:2022', 'Anhang A', 'A.5.28', 'Beweissicherung', 'offen', NULL, NULL, NULL, 584, 29, '2026-09-22 15:58:55', 29, '2026-09-22 16:05:10', 'Wie sichern Sie bei Sicherheitsvorfällen relevante Beweise, z. B. Logdateien, Screenshots oder E-Mails?\r\nWelche Maßnahmen ergreifen Sie, um die Integrität und Nachvollziehbarkeit dieser Beweise zu gewährleisten, z. B. Hash-Werte, Zeitstempel, Zugriffsschutz?\r\nWo und wie lange bewahren Sie diese Beweise auf?\r\nHaben Sie geprüft, welche Anforderungen für eine mögliche rechtliche Verwertbarkeit gelten, z. B. für Strafanzeigen oder Versicherungsfälle?'),
(329, 6, 585, 'ISO/IEC 27001:2022', 'Anhang A', 'A.5.29', 'Informationssicherheit in Notfällen', 'offen', NULL, NULL, NULL, 585, 29, '2026-09-22 15:58:55', 29, '2026-09-22 16:05:10', 'Verfügen Sie über Notfall- oder Krisenpläne, und berücksichtigen diese explizit die Informationssicherheit Ihrer SaaS-Plattform und Kundendaten?\r\nWie stellen Sie sicher, dass Schutzziele auch unter Stressbedingungen eingehalten werden, z. B. bei Systemausfällen oder Cyberangriffen?\r\nWelche Dokumente belegen Ihre Notfallplanung, z. B. Notfallhandbuch, Kontaktlisten, Wiederanlaufpläne?\r\nWann wurden diese Pläne zuletzt getestet oder aktualisiert?'),
(330, 6, 586, 'ISO/IEC 27001:2022', 'Anhang A', 'A.5.30', 'IKT-Bereitschaft für Business Continuity', 'offen', NULL, NULL, NULL, 586, 29, '2026-09-22 15:58:55', 29, '2026-09-22 16:05:10', 'Welche Ihrer Geschäftsprozesse sind kritisch für den Betrieb Ihrer SaaS-Lösung und die Erfüllung von Kundenverträgen?\r\nWie haben Sie geplant, diese kritischen IT-Systeme bei Störungen fortzuführen, z. B. durch Backups, redundante Systeme oder Ausweichverfahren?\r\nWelche Dokumentation belegt Ihre IKT-Bereitschaftsplanung, z. B. Business-Impact-Analyse, Recovery-Pläne, RTO/RPO-Definitionen?\r\nWurden diese Pläne bereits getestet, und wenn ja, mit welchem Ergebnis?'),
(331, 6, 587, 'ISO/IEC 27001:2022', 'Anhang A', 'A.5.31', 'Rechtliche Anforderungen', 'offen', NULL, NULL, NULL, 587, 29, '2026-09-22 15:58:55', 29, '2026-09-22 16:05:10', 'Wie identifizieren Sie relevante gesetzliche, regulatorische und vertragliche Anforderungen für Ihre ISMS-Software, z. B. DSGVO, Telekommunikationsrecht oder Kundenverträge?\r\nWo dokumentieren Sie diese Pflichten und deren Umsetzungsstatus, z. B. in einem Rechtskataster oder einer Anforderungsliste?\r\nWie stellen Sie sicher, dass Änderungen in der Rechtslage erkannt und umgesetzt werden?\r\nWer ist für die Überwachung rechtlicher Anforderungen verantwortlich?'),
(332, 6, 588, 'ISO/IEC 27001:2022', 'Anhang A', 'A.5.32', 'Geistiges Eigentum', 'offen', NULL, NULL, NULL, 588, 29, '2026-09-22 15:58:55', 29, '2026-09-22 16:05:10', 'Wie schützen Sie das geistige Eigentum Ihrer ISMS-Software, z. B. Quellcode, Dokumentation oder Know-how?\r\nWie stellen Sie sicher, dass eingesetzte Drittanbieter-Software lizenzkonform genutzt wird, z. B. durch Lizenzübersichten oder regelmäßige Prüfungen?\r\nWelche Nachweise gibt es für den Schutz und die Lizenzverwaltung, z. B. Lizenzverträge, Inventarlisten, Geheimhaltungsvereinbarungen?\r\nWie sind Zugriffsrechte auf sensiblen Quellcode geregelt?'),
(333, 6, 589, 'ISO/IEC 27001:2022', 'Anhang A', 'A.5.33', 'Schutz von Aufzeichnungen', 'offen', NULL, NULL, NULL, 589, 29, '2026-09-22 15:58:55', 29, '2026-09-22 16:05:10', 'Welche Aufzeichnungen sind für Ihr ISMS relevant, z. B. Auditprotokolle, Vorfallsdokumentationen oder Verträge?\r\nWie schützen Sie diese vor unbefugtem Zugriff, Verlust oder Veränderung?\r\nNach welchen Fristen löschen Sie Aufzeichnungen, und wie stellen Sie die Einhaltung sicher, z. B. durch Aufbewahrungsrichtlinie oder automatisierte Löschprozesse?\r\nWo sind Aufbewahrungsfristen und Verantwortlichkeiten dokumentiert?'),
(334, 6, 590, 'ISO/IEC 27001:2022', 'Anhang A', 'A.5.34', 'Datenschutz', 'offen', NULL, NULL, NULL, 590, 29, '2026-09-22 15:58:55', 29, '2026-09-22 16:05:10', 'Welche personenbezogenen Daten verarbeiten Sie im Rahmen Ihrer ISMS-Software und internen Prozesse?\r\nWelche technischen und organisatorischen Maßnahmen setzen Sie zum Schutz dieser Daten um, z. B. Verschlüsselung, Zugriffsbeschränkungen, Pseudonymisierung?\r\nWie dokumentieren Sie diese Maßnahmen, z. B. im Verzeichnis von Verarbeitungstätigkeiten oder in technisch-organisatorischen Maßnahmen (TOM)?\r\nWie stimmen Sie sich mit Ihrem Datenschutzbeauftragten oder externen Datenschutzverantwortlichen ab?'),
(335, 6, 591, 'ISO/IEC 27001:2022', 'Anhang A', 'A.5.35', 'Unabhängige Sicherheitsprüfung', 'offen', NULL, NULL, NULL, 591, 29, '2026-09-22 15:58:55', 29, '2026-09-22 16:05:10', 'Wurden Ihre Sicherheitsmaßnahmen und -prozesse bereits unabhängig geprüft, z. B. durch externe Auditoren, Penetrationstests oder Zertifizierungsaudits?\r\nIn welchen Abständen planen Sie solche unabhängigen Prüfungen?\r\nWelche Nachweise gibt es für durchgeführte Prüfungen, z. B. Auditberichte, Testprotokolle oder Zertifikate?\r\nWie gehen Sie mit den Ergebnissen und Empfehlungen aus diesen Prüfungen um?'),
(336, 6, 592, 'ISO/IEC 27001:2022', 'Anhang A', 'A.5.36', 'Einhaltung von Richtlinien', 'offen', NULL, NULL, NULL, 592, 29, '2026-09-22 15:58:55', 29, '2026-09-22 16:05:10', 'Wie überprüfen Sie regelmäßig, ob Ihre internen Sicherheitsvorgaben eingehalten werden, z. B. durch Stichproben, Self-Assessments oder interne Audits?\r\nWelche Dokumentation belegt diese Prüfungen, z. B. Checklisten, Prüfprotokolle oder Maßnahmenlisten?\r\nWie gehen Sie bei festgestellten Abweichungen vor, und wer ist für die Einleitung von Korrekturmaßnahmen verantwortlich?\r\nKönnen Sie ein Beispiel für eine erkannte Abweichung und die daraus abgeleitete Maßnahme nennen?'),
(337, 6, 593, 'ISO/IEC 27001:2022', 'Anhang A', 'A.5.37', 'Technische Compliance', 'offen', NULL, NULL, NULL, 593, 29, '2026-09-22 15:58:55', 29, '2026-09-22 16:05:10', 'Welche technischen Vorgaben, Baselines oder Standards gelten für Ihre IT-Systeme, z. B. Härtungsvorgaben, Patch-Zyklen oder Konfigurationsstandards?\r\nWie kontrollieren Sie systematisch die Einhaltung dieser Vorgaben, z. B. durch automatisierte Scans, manuelle Prüfungen oder Konfigurationsmanagement?\r\nWelche Nachweise dokumentieren die technische Compliance, z. B. Scan-Berichte, Konfigurationsprotokolle oder Prüfberichte?\r\nWie gehen Sie mit Abweichungen um?'),
(338, 6, 594, 'ISO/IEC 27001:2022', 'Anhang A', 'A.6.1', 'Hintergrundprüfungen', 'offen', NULL, NULL, NULL, 594, 29, '2026-09-22 15:58:55', 29, '2026-09-22 16:05:10', 'Führen Sie vor der Einstellung neuer Mitarbeitender sicherheitsrelevante Prüfungen durch, z. B. Überprüfung von Zeugnissen, Referenzen oder polizeilichen Führungszeugnissen?\r\nWie stellen Sie sicher, dass diese Prüfungen im rechtlich zulässigen Rahmen erfolgen?\r\nWelche Nachweise dokumentieren durchgeführte Hintergrundprüfungen, z. B. Checklisten, Kopien oder Vermerke in der Personalakte?\r\nGibt es auch während der Beschäftigung anlassbezogene Prüfungen?'),
(339, 6, 595, 'ISO/IEC 27001:2022', 'Anhang A', 'A.6.2', 'Arbeitsverträge', 'offen', NULL, NULL, NULL, 595, 29, '2026-09-22 15:58:55', 29, '2026-09-22 16:05:10', 'Wie verankern Sie Sicherheitsanforderungen und -pflichten in Arbeitsverträgen oder ergänzenden Dokumenten, z. B. Vertraulichkeitsvereinbarungen, IT-Nutzungsrichtlinien oder Verpflichtungserklärungen?\r\nWelche konkreten Sicherheitspflichten sind dort festgehalten, z. B. Geheimhaltung, Passwortschutz oder Meldepflichten bei Vorfällen?\r\nWo werden diese Dokumente aufbewahrt, z. B. in der Personalakte?\r\nWie stellen Sie sicher, dass alle Mitarbeitenden diese Dokumente erhalten und bestätigen?'),
(340, 6, 596, 'ISO/IEC 27001:2022', 'Anhang A', 'A.6.3', 'Sensibilisierung und Schulung', 'offen', NULL, NULL, NULL, 596, 29, '2026-09-22 15:58:55', 29, '2026-09-22 16:05:10', 'Wie schulen und sensibilisieren Sie Ihre Mitarbeitenden regelmäßig zu Informationssicherheitsthemen, z. B. durch Onboarding-Schulungen, E-Learnings oder Team-Briefings?\r\nWelche Themen werden abgedeckt, z. B. Phishing-Erkennung, Passwortregeln, Umgang mit Kundendaten oder Meldung von Vorfällen?\r\nWelche Nachweise dokumentieren die durchgeführten Schulungen, z. B. Teilnehmerlisten, Schulungsprotokolle oder Zertifikate?\r\nWie stellen Sie sicher, dass auch neue Mitarbeitende zeitnah geschult werden?'),
(341, 6, 597, 'ISO/IEC 27001:2022', 'Anhang A', 'A.6.4', 'Disziplinarische Maßnahmen', 'offen', NULL, NULL, NULL, 597, 29, '2026-09-22 15:58:55', 29, '2026-09-22 16:05:10', 'Existiert eine Regelung, die abgestufte Konsequenzen bei Verstößen gegen Sicherheitsvorgaben festlegt, z. B. in einer Arbeitsordnung, einem Mitarbeiterhandbuch oder einer ISMS-Richtlinie?\r\nWie werden Mitarbeitende über mögliche Konsequenzen bei Sicherheitsverstößen informiert?\r\nWer entscheidet bei Ihnen über disziplinarische Maßnahmen und wie wird dabei die Verhältnismäßigkeit sichergestellt?\r\nWie dokumentieren Sie Sicherheitsverstöße und die darauf folgenden Maßnahmen?'),
(342, 6, 598, 'ISO/IEC 27001:2022', 'Anhang A', 'A.6.5', 'Verantwortlichkeiten nach Beendigung', 'offen', NULL, NULL, NULL, 598, 29, '2026-09-22 15:58:55', 29, '2026-09-22 16:05:10', 'Welche vertraglichen Regelungen stellen sicher, dass Vertraulichkeitspflichten auch nach dem Ausscheiden eines Mitarbeitenden fortbestehen, z. B. nachvertragliche Klauseln im Arbeitsvertrag oder separate Vereinbarungen?\r\nWie kommunizieren Sie beim Offboarding die fortgeltenden Pflichten zum Schutz von Unternehmensinformationen?\r\nWelche Fristen gelten für die Vertraulichkeitspflichten nach Austritt und wo sind diese dokumentiert?'),
(343, 6, 599, 'ISO/IEC 27001:2022', 'Anhang A', 'A.6.6', 'Vertraulichkeitsvereinbarungen', 'offen', NULL, NULL, NULL, 599, 29, '2026-09-22 15:58:55', 29, '2026-09-22 16:05:10', 'Für welche Rollen und externen Partner bestehen bei Ihnen Vertraulichkeitsvereinbarungen, z. B. NDAs mit Freelancern, Subunternehmern oder Kunden?\r\nWie stellen Sie sicher, dass Vertraulichkeitsvereinbarungen vor Zugang zu sensiblen Informationen unterzeichnet werden?\r\nWo werden die unterschriebenen Vereinbarungen aufbewahrt und wer prüft deren Vollständigkeit?\r\nWann wurden die Vorlagen zuletzt auf Aktualität geprüft?'),
(344, 6, 600, 'ISO/IEC 27001:2022', 'Anhang A', 'A.6.7', 'Remote Work', 'offen', NULL, NULL, NULL, 600, 29, '2026-09-22 15:58:55', 29, '2026-09-22 16:05:10', 'Welche schriftliche Regelung definiert Anforderungen für Remote Work und Homeoffice, z. B. eine Homeoffice-Richtlinie oder IT-Nutzungsordnung?\r\nWie stellen Sie sicher, dass private Netzwerke und Geräte im Homeoffice ausreichend geschützt sind, z. B. durch VPN-Pflicht oder Mindestanforderungen an WLAN-Sicherheit?\r\nWelche Vorgaben gelten für den Umgang mit sensiblen Kundendaten beim mobilen Arbeiten?\r\nWie kontrollieren Sie die Einhaltung dieser Regelungen?'),
(345, 6, 601, 'ISO/IEC 27001:2022', 'Anhang A', 'A.6.8', 'Meldung von Sicherheitsereignissen', 'offen', NULL, NULL, NULL, 601, 29, '2026-09-22 15:58:55', 29, '2026-09-22 16:05:10', 'Über welche Kanäle können Ihre Mitarbeitenden Sicherheitsauffälligkeiten melden, z. B. E-Mail-Adresse, Ticketsystem oder direkter Ansprechpartner?\r\nWie sind die Meldekanäle dokumentiert und wie werden neue Mitarbeitende darüber informiert?\r\nInnerhalb welcher Zeitvorgaben sollen Sicherheitsereignisse gemeldet werden?\r\nWie stellen Sie sicher, dass auch externe Berater oder Freelancer die Meldewege kennen?'),
(346, 6, 602, 'ISO/IEC 27001:2022', 'Anhang A', 'A.7.1', 'Sicherheitszonen', 'offen', NULL, NULL, NULL, 602, 29, '2026-09-22 15:58:55', 29, '2026-09-22 16:05:10', 'Haben Sie Bereiche mit unterschiedlichem Schutzbedarf definiert, z. B. Serverraum, Entwicklungsbereich oder Büro?\r\nWelche Zutrittsmaßnahmen schützen die jeweiligen Bereiche, z. B. Schlüssel, Codes, Chipkarten?\r\nWo ist dokumentiert, welche Zonen welchen Schutz erfordern und wer Zutritt hat?\r\nWie berücksichtigen Sie Ihre Büroräume als SaaS-Anbieter hinsichtlich Zugang zu Produktivsystemen?'),
(347, 6, 603, 'ISO/IEC 27001:2022', 'Anhang A', 'A.7.2', 'Zutrittskontrolle', 'offen', NULL, NULL, NULL, 603, 29, '2026-09-22 15:58:55', 29, '2026-09-22 16:05:10', 'Wie kontrollieren Sie den physischen Zugang zu Ihren Geschäftsräumen, z. B. durch Schlüsselvergabe, Schließanlage oder Zutrittskontrollsystem?\r\nWer verwaltet die Schlüssel oder Zugangsmittel und führt darüber eine aktuelle Liste?\r\nWie protokollieren Sie Zutritte zu sensiblen Bereichen und wie lange bewahren Sie die Aufzeichnungen auf?\r\nWann haben Sie zuletzt geprüft, ob nur berechtigte Personen Zugang haben?'),
(348, 6, 604, 'ISO/IEC 27001:2022', 'Anhang A', 'A.7.3', 'Sicherung von Büros', 'offen', NULL, NULL, NULL, 604, 29, '2026-09-22 15:58:55', 29, '2026-09-22 16:05:10', 'Wie verhindern Sie unbefugten Zugriff auf Arbeitsplätze und Unterlagen in Ihren Büroräumen, z. B. durch abschließbare Schränke oder Sichtschutzfolien?\r\nWelche Regelungen gelten für Besucher in Ihren Räumlichkeiten?\r\nWie ist sichergestellt, dass sensible Informationen nicht von Fenster oder Flur einsehbar sind?'),
(349, 6, 605, 'ISO/IEC 27001:2022', 'Anhang A', 'A.7.4', 'Physische Überwachung', 'offen', NULL, NULL, NULL, 605, 29, '2026-09-22 15:58:55', 29, '2026-09-22 16:05:10', 'Setzen Sie Überwachungsmaßnahmen für sicherheitsrelevante Bereiche ein, z. B. Videoüberwachung, Bewegungsmelder oder Alarmanlagen?\r\nFalls ja, wie sind diese Maßnahmen dokumentiert und wer wertet Aufzeichnungen aus?\r\nFalls nein, wie begründen Sie den Verzicht angesichts des Schutzbedarfs Ihrer IT-Infrastruktur?'),
(350, 6, 606, 'ISO/IEC 27001:2022', 'Anhang A', 'A.7.5', 'Schutz vor Umweltgefahren', 'offen', NULL, NULL, NULL, 606, 29, '2026-09-22 15:58:55', 29, '2026-09-22 16:05:10', 'Welche Schutzmaßnahmen haben Sie gegen Umweltgefahren getroffen, z. B. Rauchmelder, Feuerlöscher, USV für Server?\r\nWie schützen Sie Ihre Entwicklungs- und Produktivsysteme vor Stromausfällen oder Wasserschäden?\r\nWann wurden Brandschutzeinrichtungen oder USV-Anlagen zuletzt geprüft und wo ist dies dokumentiert?'),
(351, 6, 607, 'ISO/IEC 27001:2022', 'Anhang A', 'A.7.6', 'Arbeiten in gesicherten Bereichen', 'offen', NULL, NULL, NULL, 607, 29, '2026-09-22 15:58:55', 29, '2026-09-22 16:05:10', 'Welche Bereiche in Ihrem Unternehmen haben erhöhten Schutzbedarf, z. B. Serverraum oder Bereich mit Kundendatenzugriff?\r\nWelche Regeln gelten für Tätigkeiten in diesen Bereichen, z. B. Vier-Augen-Prinzip oder Protokollierung?\r\nWer erteilt Freigaben für Arbeiten in gesicherten Bereichen und wie wird dies dokumentiert?'),
(352, 6, 608, 'ISO/IEC 27001:2022', 'Anhang A', 'A.7.7', 'Clear Desk / Clear Screen', 'offen', NULL, NULL, NULL, 608, 29, '2026-09-22 15:58:55', 29, '2026-09-22 16:05:10', 'Gibt es eine Clear-Desk-/Clear-Screen-Richtlinie oder vergleichbare Vorgaben, z. B. in einer IT-Nutzungsordnung?\r\nWie stellen Ihre Mitarbeitenden sicher, dass Bildschirme bei Abwesenheit gesperrt und Unterlagen weggeschlossen werden?\r\nWie sensibilisieren Sie neue Teammitglieder für diese Anforderungen?'),
(353, 6, 609, 'ISO/IEC 27001:2022', 'Anhang A', 'A.7.8', 'Standortgebundene Geräte', 'offen', NULL, NULL, NULL, 609, 29, '2026-09-22 15:58:55', 29, '2026-09-22 16:05:10', 'Wie schützen Sie Notebooks, Smartphones und andere Geräte gegen Diebstahl, z. B. durch Kensington-Schlösser, verschlossene Schränke oder Verschlüsselung?\r\nWelche Vorgaben gelten für den Transport von Geräten außerhalb des Büros?\r\nWie wird sichergestellt, dass verlorene Geräte zeitnah gemeldet und Zugänge gesperrt werden?'),
(354, 6, 610, 'ISO/IEC 27001:2022', 'Anhang A', 'A.7.9', 'Außerbetriebnahme von Geräten', 'offen', NULL, NULL, NULL, 610, 29, '2026-09-22 15:58:55', 29, '2026-09-22 16:05:10', 'Wie gehen Sie vor, wenn ein Gerät ausgesondert oder weitergegeben wird, z. B. Löschverfahren, Zerstörung von Datenträgern?\r\nWer ist für die sichere Datenlöschung verantwortlich und wie wird sie dokumentiert, z. B. durch Löschprotokolle oder Zertifikate?\r\nWelche Methode nutzen Sie, um sicherzustellen, dass Daten nicht wiederherstellbar sind?'),
(355, 6, 611, 'ISO/IEC 27001:2022', 'Anhang A', 'A.7.10', 'Lagerung von Datenträgern', 'offen', NULL, NULL, NULL, 611, 29, '2026-09-22 15:58:55', 29, '2026-09-22 16:05:10', 'Wie lagern Sie Datenträger mit sensiblen Informationen, z. B. verschlossene Schränke, Tresore oder gesicherte Räume?\r\nWer hat Zugang zu gelagerten Datenträgern und wie ist dies geregelt?\r\nWie handhaben Sie den Transport von Datenträgern, z. B. verschlüsselte USB-Sticks oder gesicherte Versandwege?'),
(356, 6, 612, 'ISO/IEC 27001:2022', 'Anhang A', 'A.7.11', 'Unterstützende Infrastruktur', 'offen', NULL, NULL, NULL, 612, 29, '2026-09-22 15:58:55', 29, '2026-09-22 16:05:10', 'Wie stellen Sie die Verfügbarkeit Ihrer Stromversorgung und Internetanbindung sicher, z. B. USV, redundante Leitungen?\r\nWer ist für Wartung und Überwachung der Gebäudetechnik zuständig?\r\nWelche Maßnahmen greifen bei Ausfall der unterstützenden Infrastruktur?'),
(357, 6, 613, 'ISO/IEC 27001:2022', 'Anhang A', 'A.7.12', 'Kabelschutz', 'offen', NULL, NULL, NULL, 613, 29, '2026-09-22 15:58:55', 29, '2026-09-22 16:05:10', 'Wie schützen Sie Strom- und Datenkabel vor Beschädigung oder unbefugtem Zugriff, z. B. durch Kabelkanäle, gesicherte Verlegewege?\r\nSind Netzwerkkabel so verlegt, dass sie nicht leicht manipuliert oder abgehört werden können?\r\nWie berücksichtigen Sie Kabelschutz bei Umbaumaßnahmen oder neuen Arbeitsplätzen?'),
(358, 6, 614, 'ISO/IEC 27001:2022', 'Anhang A', 'A.7.13', 'Wartung von Geräten', 'offen', NULL, NULL, NULL, 614, 29, '2026-09-22 15:58:55', 29, '2026-09-22 16:05:10', 'Wie stellen Sie sicher, dass Wartungsarbeiten an IT-Geräten kontrolliert und nachvollziehbar erfolgen, z. B. durch Wartungsprotokolle oder Auftragserteilung?\r\nWelche Vorgaben gelten für externe Techniker, z. B. Begleitung, Vertraulichkeitsvereinbarung?\r\nWie wird sichergestellt, dass bei Reparaturen keine sensiblen Daten offengelegt werden?'),
(359, 6, 615, 'ISO/IEC 27001:2022', 'Anhang A', 'A.7.14', 'Entsorgung', 'offen', NULL, NULL, NULL, 615, 29, '2026-09-22 15:58:55', 29, '2026-09-22 16:05:10', 'Wie entsorgen Sie Geräte und Datenträger, damit keine Daten offengelegt werden, z. B. zertifizierte Entsorgungsunternehmen, physische Zerstörung?\r\nWelche Nachweise erhalten Sie über die sichere Entsorgung, z. B. Vernichtungszertifikate?\r\nWer genehmigt die Entsorgung oder Wiederverwendung von Geräten und dokumentiert dies?'),
(360, 6, 616, 'ISO/IEC 27001:2022', 'Anhang A', 'A.8.1', 'Endgerätesicherheit', 'offen', NULL, NULL, NULL, 616, 29, '2026-09-22 15:58:55', 29, '2026-09-22 16:05:10', 'Wie härten Sie Endgeräte wie Notebooks und Smartphones, z. B. durch Verschlüsselung, Firewall, Deaktivierung ungenutzter Dienste?\r\nWie stellen Sie sicher, dass Betriebssysteme und Software zeitnah aktualisiert werden, z. B. durch automatische Updates oder Patch-Management?\r\nWelche Sicherheitssoftware setzen Sie ein, z. B. Antivirus, EDR?\r\nWie kontrollieren Sie, dass alle Entwickler-Endgeräte diese Vorgaben erfüllen?'),
(361, 6, 617, 'ISO/IEC 27001:2022', 'Anhang A', 'A.8.2', 'Privilegierte Zugriffe', 'offen', NULL, NULL, NULL, 617, 29, '2026-09-22 15:58:55', 29, '2026-09-22 16:05:10', 'Welche Personen in Ihrem Unternehmen verfügen über privilegierte Konten (z. B. Admin-Rechte für Server, Cloud-Dienste, Datenbanken)?\r\nWie stellen Sie sicher, dass privilegierte Rechte strikt getrennt von normalen Benutzerkonten genutzt werden?\r\nWelche Dokumentation führen Sie über die Vergabe und den Entzug privilegierter Zugänge, z. B. eine Berechtigungsmatrix oder Tickethistorie?\r\nWie überwachen Sie die Nutzung privilegierter Konten – etwa durch Protokollierung oder Alerts bei ungewöhnlichen Aktivitäten?\r\nIn welchen Abständen überprüfen Sie, ob vergebene Admin-Rechte noch erforderlich sind?'),
(362, 6, 618, 'ISO/IEC 27001:2022', 'Anhang A', 'A.8.3', 'Informationszugriff', 'offen', NULL, NULL, NULL, 618, 29, '2026-09-22 15:58:55', 29, '2026-09-22 16:05:10', 'Wie setzen Sie technisch durch, dass nur berechtigte Personen auf Ihre Systeme und Informationen zugreifen können, z. B. über Rollenkonzepte oder ACLs?\r\nWelche Protokollierung erfolgt bei Zugriffen auf geschäftskritische Daten und wie lange bewahren Sie diese Logs auf?\r\nWo dokumentieren Sie Ihre Zugriffsberechtigungen, z. B. in einer Berechtigungsmatrix oder einem IAM-System?\r\nWie gehen Sie vor, wenn ein Mitarbeiter das Unternehmen verlässt oder die Rolle wechselt?'),
(363, 6, 619, 'ISO/IEC 27001:2022', 'Anhang A', 'A.8.4', 'Quellcodezugriff', 'offen', NULL, NULL, NULL, 619, 29, '2026-09-22 15:58:55', 29, '2026-09-22 16:05:10', 'Wie schützen Sie den Quellcode Ihrer ISMS-Software vor unbefugtem Zugriff – sowohl intern als auch extern?\r\nWelches Versionskontrollsystem nutzen Sie (z. B. Git) und wie sind die Zugriffsrechte darauf geregelt?\r\nWer darf Änderungen am Quellcode vornehmen und wie werden diese freigegeben, z. B. durch Code-Reviews oder Merge-Requests?\r\nWie verhindern Sie, dass Quellcode unkontrolliert auf private Geräte oder externe Speicher kopiert wird?'),
(364, 6, 620, 'ISO/IEC 27001:2022', 'Anhang A', 'A.8.5', 'Sichere Authentisierung', 'offen', NULL, NULL, NULL, 620, 29, '2026-09-22 15:58:55', 29, '2026-09-22 16:05:10', 'Welche Authentisierungsverfahren setzen Sie für den Zugang zu Ihren Systemen ein, z. B. Passwortrichtlinien, MFA?\r\nBei welchen Systemen oder Daten mit erhöhtem Schutzbedarf nutzen Sie Multi-Faktor-Authentisierung?\r\nWie stellen Sie sicher, dass Passwörter ausreichend komplex sind und regelmäßig gewechselt werden?\r\nWelche Nachweise dokumentieren Ihre Authentisierungsrichtlinie, z. B. technische Konfiguration oder Policy-Dokument?'),
(365, 6, 621, 'ISO/IEC 27001:2022', 'Anhang A', 'A.8.6', 'Kapazitätsmanagement', 'offen', NULL, NULL, NULL, 621, 29, '2026-09-22 15:58:55', 29, '2026-09-22 16:05:10', 'Wie überwachen Sie die Auslastung Ihrer IT-Ressourcen, z. B. Speicher, CPU, Bandbreite Ihrer SaaS-Plattform?\r\nWelche Schwellwerte oder Alerts haben Sie definiert, um frühzeitig auf Kapazitätsengpässe reagieren zu können?\r\nWie planen Sie zukünftige Kapazitätsbedarfe, etwa bei wachsender Kundenzahl Ihrer Software?\r\nWelche Dokumentation belegt Ihre Kapazitätsplanung, z. B. Monitoring-Dashboards oder Planungstabellen?'),
(366, 6, 622, 'ISO/IEC 27001:2022', 'Anhang A', 'A.8.7', 'Malware-Schutz', 'offen', NULL, NULL, NULL, 622, 29, '2026-09-22 15:58:55', 29, '2026-09-22 16:05:10', 'Welche Schutzmechanismen gegen Schadsoftware setzen Sie auf Arbeitsplätzen, Servern und in der Cloud ein?\r\nWie stellen Sie sicher, dass Virensignaturen und Schutzsoftware stets aktuell sind?\r\nWie werden Malware-Vorfälle erkannt, gemeldet und behandelt?\r\nWelche Nachweise zeigen den aktuellen Schutzstatus, z. B. Management-Konsole, Update-Logs?'),
(367, 6, 623, 'ISO/IEC 27001:2022', 'Anhang A', 'A.8.8', 'Technische Schwachstellen', 'offen', NULL, NULL, NULL, 623, 29, '2026-09-22 15:58:55', 29, '2026-09-22 16:05:10', 'Wie identifizieren Sie technische Schwachstellen in Ihrer Software und Infrastruktur, z. B. durch Schwachstellenscanner, CVE-Überwachung?\r\nNach welchen Kriterien bewerten und priorisieren Sie erkannte Schwachstellen?\r\nIn welchem Zeitrahmen beheben Sie kritische Schwachstellen und wie dokumentieren Sie dies?\r\nWelche Nachweise führen Sie über durchgeführte Patches oder kompensierende Maßnahmen?'),
(368, 6, 624, 'ISO/IEC 27001:2022', 'Anhang A', 'A.8.9', 'Konfigurationsmanagement', 'offen', NULL, NULL, NULL, 624, 29, '2026-09-22 15:58:55', 29, '2026-09-22 16:05:10', 'Wie definieren Sie sichere Basiskonfigurationen für Ihre Systeme, z. B. Hardening-Guides, Standard-Images?\r\nWie stellen Sie sicher, dass Konfigurationsänderungen nur autorisiert erfolgen?\r\nWelche Dokumentation belegt Ihre Soll-Konfigurationen und deren Einhaltung, z. B. Konfigurations-Datenbank, Audit-Logs?\r\nWie prüfen Sie regelmäßig, ob Systeme noch der definierten Baseline entsprechen?'),
(369, 6, 625, 'ISO/IEC 27001:2022', 'Anhang A', 'A.8.10', 'Informationslöschung', 'offen', NULL, NULL, NULL, 625, 29, '2026-09-22 15:58:55', 29, '2026-09-22 16:05:10', 'Wie stellen Sie sicher, dass Daten bei Löschung oder Außerbetriebnahme von Geräten nicht wiederherstellbar sind?\r\nWelche Löschverfahren nutzen Sie für unterschiedliche Datenträger, z. B. Secure Erase, physische Vernichtung, Cloud-Löschung?\r\nWie dokumentieren Sie durchgeführte Löschungen, z. B. Löschprotokolle oder Vernichtungsnachweise?\r\nWie gehen Sie mit der Löschung von Kundendaten in Ihrer SaaS-Lösung um?'),
(370, 6, 626, 'ISO/IEC 27001:2022', 'Anhang A', 'A.8.11', 'Datenmaskierung', 'offen', NULL, NULL, NULL, 626, 29, '2026-09-22 15:58:55', 29, '2026-09-22 16:05:10', 'In welchen Fällen maskieren oder anonymisieren Sie sensible Daten, z. B. in Testumgebungen oder bei Support-Anfragen?\r\nWelche Techniken setzen Sie zur Datenmaskierung ein, z. B. Pseudonymisierung, Tokenisierung?\r\nWie stellen Sie sicher, dass Produktivdaten nicht unverändert in Testumgebungen gelangen?\r\nWelche Dokumentation belegt Ihre Vorgehensweise zur Datenmaskierung?'),
(371, 6, 627, 'ISO/IEC 27001:2022', 'Anhang A', 'A.8.12', 'Datenverlustprävention', 'offen', NULL, NULL, NULL, 627, 29, '2026-09-22 15:58:55', 29, '2026-09-22 16:05:10', 'Welche Maßnahmen verhindern, dass sensible Daten unkontrolliert das Unternehmen verlassen, z. B. E-Mail-Filter, USB-Sperrung?\r\nWie erkennen Sie unerlaubte Datenübertragungen oder -speicherungen?\r\nWelche sensiblen Daten haben Sie identifiziert, die besonderen Schutz vor Abfluss benötigen?\r\nWelche Nachweise dokumentieren Ihre DLP-Maßnahmen, z. B. Richtlinien, technische Konfigurationen?'),
(372, 6, 628, 'ISO/IEC 27001:2022', 'Anhang A', 'A.8.13', 'Datensicherung', 'offen', NULL, NULL, NULL, 628, 29, '2026-09-22 15:58:55', 29, '2026-09-22 16:05:10', 'Wie häufig erstellen Sie Backups Ihrer geschäftskritischen Daten und Systeme?\r\nWo werden Backups aufbewahrt und wie sind sie gegen unbefugten Zugriff und physische Risiken geschützt?\r\nWann haben Sie zuletzt eine vollständige Wiederherstellung getestet und wie wurde das Ergebnis dokumentiert?\r\nWelche Backup-Konzepte oder -Richtlinien existieren für Ihre SaaS-Kundendaten?'),
(373, 6, 629, 'ISO/IEC 27001:2022', 'Anhang A', 'A.8.14', 'Redundanz', 'offen', NULL, NULL, NULL, 629, 29, '2026-09-22 15:58:55', 29, '2026-09-22 16:05:10', 'Welche Verfügbarkeitsziele haben Sie für Ihre ISMS-Software und kritische interne Systeme definiert?\r\nWelche Redundanzmechanismen setzen Sie ein, um Ausfälle abzufangen, z. B. Cloud-Verfügbarkeitszonen, gespiegelte Datenbanken?\r\nWie haben Sie geprüft, ob die Redundanz im Ernstfall funktioniert?\r\nWelche Dokumentation belegt Ihre Redundanzstrategie, z. B. Architekturdiagramme, SLAs?'),
(374, 6, 630, 'ISO/IEC 27001:2022', 'Anhang A', 'A.8.15', 'Protokollierung', 'offen', NULL, NULL, NULL, 630, 29, '2026-09-22 15:58:55', 29, '2026-09-22 16:05:10', 'Welche sicherheitsrelevanten Ereignisse protokollieren Sie, z. B. Logins, Admin-Aktionen, Zugriffe auf sensible Daten?\r\nWie schützen Sie Logs vor Manipulation oder unbefugter Löschung?\r\nWie lange bewahren Sie Protokolle auf und wo ist dies geregelt?\r\nWelche Systeme oder Tools nutzen Sie zur zentralen Logverwaltung?'),
(375, 6, 631, 'ISO/IEC 27001:2022', 'Anhang A', 'A.8.16', 'Monitoring', 'offen', NULL, NULL, NULL, 631, 29, '2026-09-22 15:58:55', 29, '2026-09-22 16:05:10', 'Wie überwachen Sie Ihre Systeme auf Anomalien, Angriffe oder Störungen, z. B. durch SIEM, Alerting?\r\nWelche Schwellwerte oder Regeln lösen Alarme aus?\r\nWie schnell können Sie auf erkannte Sicherheitsereignisse reagieren und wer ist verantwortlich?\r\nWelche Nachweise belegen Ihr Monitoring, z. B. Dashboards, Alarmlisten, Incident-Tickets?'),
(376, 6, 632, 'ISO/IEC 27001:2022', 'Anhang A', 'A.8.17', 'Uhrzeitsynchronisation', 'offen', NULL, NULL, NULL, 632, 29, '2026-09-22 15:58:55', 29, '2026-09-22 16:05:10', 'Wie stellen Sie sicher, dass alle Ihre Systeme eine konsistente Zeitbasis nutzen?\r\nWelche Zeitquelle verwenden Sie, z. B. NTP-Server, und wie ist die Synchronisation konfiguriert?\r\nWie überprüfen Sie, dass die Zeitsynchronisation funktioniert und keine Abweichungen auftreten?\r\nWelche Dokumentation belegt Ihre Konfiguration zur Uhrzeitsynchronisation?'),
(377, 6, 633, 'ISO/IEC 27001:2022', 'Anhang A', 'A.8.18', 'Nutzung privilegierter Programme', 'offen', NULL, NULL, NULL, 633, 29, '2026-09-22 15:58:55', 29, '2026-09-22 16:05:10', 'Welche administrativen Tools oder Befehle werden in Ihrem Unternehmen genutzt, z. B. Remote-Admin, Skripte, Systemwerkzeuge?\r\nWie kontrollieren Sie, wer diese Tools nutzen darf?\r\nWie wird die Nutzung privilegierter Programme protokolliert und nachvollziehbar gemacht?\r\nWelche Einschränkungen oder Freigabeprozesse existieren für den Einsatz solcher Werkzeuge?'),
(378, 6, 634, 'ISO/IEC 27001:2022', 'Anhang A', 'A.8.19', 'Softwareinstallation', 'offen', NULL, NULL, NULL, 634, 29, '2026-09-22 15:58:55', 29, '2026-09-22 16:05:10', 'Wie stellen Sie sicher, dass Software nur kontrolliert und aus vertrauenswürdigen Quellen installiert wird?\r\nWelchen Freigabeprozess durchlaufen neue Softwareinstallationen, z. B. Genehmigung durch IT-Verantwortlichen?\r\nWie verhindern Sie, dass Mitarbeiter eigenständig nicht autorisierte Software installieren?\r\nWelche Dokumentation führen Sie über installierte Software, z. B. Softwareinventar, Freigabelisten?'),
(379, 6, 635, 'ISO/IEC 27001:2022', 'Anhang A', 'A.8.20', 'Netzwerksicherheit', 'offen', NULL, NULL, NULL, 635, 29, '2026-09-22 15:58:55', 29, '2026-09-22 16:05:10', 'Wie ist Ihr Netzwerk segmentiert, um unterschiedliche Schutzbereiche zu trennen, z. B. Entwicklung, Produktion, Gäste-WLAN?\r\nWelche Firewall-Regeln oder Zugriffskontrollen schützen Ihre Netzwerke nach außen und innen?\r\nWie regeln Sie externe Verbindungen, z. B. VPN, Cloud-Anbindungen?\r\nWelche Dokumentation belegt Ihre Netzwerkarchitektur und Sicherheitsmaßnahmen, z. B. Netzwerkdiagramme, Firewall-Regelwerke?'),
(380, 6, 636, 'ISO/IEC 27001:2022', 'Anhang A', 'A.8.21', 'Netzwerkdienste', 'offen', NULL, NULL, NULL, 636, 29, '2026-09-22 15:58:55', 29, '2026-09-22 16:05:10', 'Welche Netzwerkdienste stellen Sie bereit und wie stellen Sie sicher, dass nur benötigte Dienste aktiv sind?\r\nWie sind diese Dienste sicher konfiguriert, z. B. Verschlüsselung, Zugriffsbeschränkung?\r\nWie überwachen Sie Netzwerkdienste auf Verfügbarkeit und Sicherheitsprobleme?\r\nWelche Nachweise dokumentieren die Konfiguration und Freigabe Ihrer Netzwerkdienste?'),
(381, 6, 637, 'ISO/IEC 27001:2022', 'Anhang A', 'A.8.22', 'Trennung von Netzwerken', 'offen', NULL, NULL, NULL, 637, 29, '2026-09-22 15:58:55', 29, '2026-09-22 16:05:10', 'Wie ist Ihr Netzwerk segmentiert, um z. B. Entwicklungsumgebungen, Cloud-Dienste und interne Systeme voneinander zu trennen?\r\nWelche technischen Maßnahmen setzen Sie ein, um den Datenverkehr zwischen Segmenten zu kontrollieren, z. B. Firewalls, VLANs oder Cloud-Netzwerkgruppen?\r\nWie stellen Sie sicher, dass ein kompromittiertes System nicht auf andere Netzwerkbereiche zugreifen kann?\r\nWelche Dokumentation belegt Ihre Netzwerktopologie und Segmentierungsregeln, z. B. Netzwerkdiagramme, Firewall-Regelsätze?'),
(382, 6, 638, 'ISO/IEC 27001:2022', 'Anhang A', 'A.8.23', 'Webfilterung', 'offen', NULL, NULL, NULL, 638, 29, '2026-09-22 15:58:55', 29, '2026-09-22 16:05:10', 'Wie kontrollieren Sie den Webzugriff Ihrer Mitarbeitenden, um den Aufruf schädlicher oder unerwünschter Inhalte zu verhindern?\r\nWelche technischen Lösungen nutzen Sie für Webfilterung, z. B. DNS-Filter, Proxy, Browser-Erweiterungen oder Cloud-basierte Dienste?\r\nWie werden Richtlinien zu erlaubten und gesperrten Webkategorien definiert und kommuniziert?\r\nWelche Nachweise dokumentieren Ihre Filterregeln und deren Wirksamkeit, z. B. Konfigurationsprotokolle, Blockierungsberichte?'),
(383, 6, 639, 'ISO/IEC 27001:2022', 'Anhang A', 'A.8.24', 'Kryptografische Verfahren', 'offen', NULL, NULL, NULL, 639, 29, '2026-09-22 15:58:55', 29, '2026-09-22 16:05:10', 'Für welche Daten und Übertragungswege setzen Sie Verschlüsselung ein, z. B. Kundendaten, SaaS-Kommunikation, Backups?\r\nWie haben Sie den Schutzbedarf ermittelt, der die Wahl der Verschlüsselungsverfahren begründet?\r\nWelche Algorithmen und Protokolle verwenden Sie für Datenübertragung und -speicherung, z. B. TLS 1.3, AES-256?\r\nWelche Dokumente belegen Ihre Kryptografie-Richtlinie oder die Konfiguration verschlüsselter Dienste, z. B. TLS-Zertifikate, Verschlüsselungskonzept?'),
(384, 6, 640, 'ISO/IEC 27001:2022', 'Anhang A', 'A.8.25', 'Schlüsselmanagement', 'offen', NULL, NULL, NULL, 640, 29, '2026-09-22 15:58:55', 29, '2026-09-22 16:05:10', 'Wie erzeugen, speichern und verwalten Sie kryptografische Schlüssel für Ihre SaaS-Anwendung und interne Systeme?\r\nWer ist für das Schlüsselmanagement verantwortlich und wie ist der Zugriff auf Schlüssel beschränkt?\r\nNach welchen Kriterien und in welchen Intervallen rotieren Sie Schlüssel bzw. nehmen alte Schlüssel außer Betrieb?\r\nWelche Nachweise dokumentieren den Schlüssel-Lebenszyklus, z. B. Schlüsselinventar, Key-Management-Logs, Verfahrensanweisung?'),
(385, 6, 641, 'ISO/IEC 27001:2022', 'Anhang A', 'A.8.26', 'Sichere Entwicklung', 'offen', NULL, NULL, NULL, 641, 29, '2026-09-22 15:58:55', 29, '2026-09-22 16:05:10', 'Wie sind Sicherheitsanforderungen in Ihrem Entwicklungsprozess für die ISMS-Software verankert?\r\nWelche Rollen sind für die Definition und Prüfung von Sicherheitsanforderungen zuständig?\r\nWelche Methoden nutzen Sie, um Sicherheitsaspekte in Anforderungen, Design und Implementierung zu berücksichtigen, z. B. Threat Modeling, Security User Stories?\r\nWelche Dokumente belegen Ihre Entwicklungsrichtlinie mit Sicherheitsvorgaben, z. B. Secure-Development-Policy, Definition of Done?'),
(386, 6, 642, 'ISO/IEC 27001:2022', 'Anhang A', 'A.8.27', 'Sichere Architektur', 'offen', NULL, NULL, NULL, 642, 29, '2026-09-22 15:58:55', 29, '2026-09-22 16:05:10', 'Wie berücksichtigen Sie Sicherheitsprinzipien wie Minimierung von Angriffsflächen und Defense-in-Depth beim Architekturentwurf Ihrer Software?\r\nWelche Maßnahmen zur Trennung von Komponenten und Berechtigungen haben Sie in der Systemarchitektur umgesetzt?\r\nWer ist für die Bewertung und Freigabe von Architekturentscheidungen unter Sicherheitsaspekten verantwortlich?\r\nWelche Nachweise dokumentieren Ihre Sicherheitsarchitektur, z. B. Architekturdiagramme, Threat-Model-Dokumentation?'),
(387, 6, 643, 'ISO/IEC 27001:2022', 'Anhang A', 'A.8.28', 'Sicheres Coding', 'offen', NULL, NULL, NULL, 643, 29, '2026-09-22 15:58:55', 29, '2026-09-22 16:05:10', 'Welche Coding-Richtlinien setzen Sie ein, um typische Sicherheitslücken wie Injection oder unsichere Authentifizierung zu vermeiden?\r\nWie stellen Sie sicher, dass alle Entwickler diese Standards kennen und anwenden, z. B. durch Schulungen, Checklisten?\r\nWelche Code-Review-Verfahren nutzen Sie, um Sicherheitsmängel vor dem Merge zu erkennen?\r\nWelche Dokumente belegen Ihre Secure-Coding-Standards, z. B. Entwicklerhandbuch, Review-Protokolle, Linter-Konfigurationen?'),
(388, 6, 644, 'ISO/IEC 27001:2022', 'Anhang A', 'A.8.29', 'Sicherheitstests', 'offen', NULL, NULL, NULL, 644, 29, '2026-09-22 15:58:55', 29, '2026-09-22 16:05:10', 'Wie planen und führen Sie Sicherheitstests durch, bevor neue Releases Ihrer ISMS-Software produktiv gehen?\r\nWelche Testmethoden nutzen Sie, z. B. statische Code-Analyse, Penetrationstests, automatisierte Schwachstellenscans?\r\nWer ist für die Durchführung und Auswertung der Sicherheitstests verantwortlich?\r\nWelche Nachweise dokumentieren Testergebnisse und deren Behebung, z. B. Testberichte, Issue-Tracker-Einträge, Scan-Reports?'),
(389, 6, 645, 'ISO/IEC 27001:2022', 'Anhang A', 'A.8.30', 'Externe Entwicklung', 'offen', NULL, NULL, NULL, 645, 29, '2026-09-22 15:58:55', 29, '2026-09-22 16:05:10', 'Arbeiten Sie mit externen Entwicklern oder Dienstleistern zusammen und wie steuern Sie deren Sicherheitsanforderungen?\r\nWelche vertraglichen Regelungen zur Informationssicherheit haben Sie mit externen Entwicklungspartnern vereinbart, z. B. NDAs, Security-Klauseln?\r\nWie kontrollieren Sie die Einhaltung dieser Anforderungen, z. B. durch Code-Reviews, Audits, Nachweispflichten?\r\nWelche Dokumente belegen die Sicherheitsvorgaben für externe Entwicklung, z. B. Verträge, Lieferantenbewertungen?'),
(390, 6, 646, 'ISO/IEC 27001:2022', 'Anhang A', 'A.8.31', 'Produktionsumgebung', 'offen', NULL, NULL, NULL, 646, 29, '2026-09-22 15:58:55', 29, '2026-09-22 16:05:10', 'Wie ist der Zugriff auf Ihre Produktionssysteme geregelt und auf welchen Personenkreis beschränkt?\r\nWelche technischen Schutzmaßnahmen gelten für Produktionsumgebungen, z. B. gehärtete Konfigurationen, Zugriffsprotokollierung?\r\nWie stellen Sie sicher, dass Änderungen an Produktionssystemen nur kontrolliert und nachvollziehbar erfolgen?\r\nWelche Nachweise dokumentieren den Schutz Ihrer Produktionsumgebung, z. B. Zugriffsberechtigungslisten, Audit-Logs, Härtungsdokumentation?'),
(391, 6, 647, 'ISO/IEC 27001:2022', 'Anhang A', 'A.8.32', 'Änderungsmanagement', 'offen', NULL, NULL, NULL, 647, 29, '2026-09-22 15:58:55', 29, '2026-09-22 16:05:10', 'Wie ist Ihr Änderungsmanagement-Prozess für Software und Infrastruktur organisiert?\r\nWer bewertet und gibt Änderungen frei, bevor sie umgesetzt werden?\r\nWie dokumentieren Sie durchgeführte Änderungen und deren Auswirkungen, z. B. Change-Tickets, Release-Notes?\r\nWelche Nachweise belegen Ihren Change-Management-Prozess, z. B. Verfahrensanweisung, Change-Log, Genehmigungsprotokolle?'),
(392, 6, 648, 'ISO/IEC 27001:2022', 'Anhang A', 'A.8.33', 'Testdaten', 'offen', NULL, NULL, NULL, 648, 29, '2026-09-22 15:58:55', 29, '2026-09-22 16:05:10', 'Wie gehen Sie mit Testdaten um, insbesondere wenn diese personenbezogene oder vertrauliche Informationen enthalten könnten?\r\nWelche Maßnahmen zur Anonymisierung oder Maskierung von Testdaten setzen Sie ein?\r\nWer ist für die Freigabe und Kontrolle von Testdaten verantwortlich?\r\nWelche Dokumente belegen Ihre Vorgaben zum Umgang mit Testdaten, z. B. Testdaten-Richtlinie, Anonymisierungsprotokolle?'),
(393, 6, 649, 'ISO/IEC 27001:2022', 'Anhang A', 'A.8.34', 'Trennung Test/Produktion', 'offen', NULL, NULL, NULL, 649, 29, '2026-09-22 15:58:55', 29, '2026-09-22 16:05:10', 'Wie trennen Sie Ihre Test- und Entwicklungsumgebungen von der Produktivumgebung Ihrer SaaS-Lösung?\r\nWelche technischen und organisatorischen Maßnahmen verhindern, dass Produktivdaten unkontrolliert in Testumgebungen gelangen?\r\nWie stellen Sie sicher, dass Änderungen in Testumgebungen nicht versehentlich Produktionssysteme beeinflussen?\r\nWelche Nachweise dokumentieren die Trennung, z. B. Umgebungsübersicht, Zugriffsregelungen, Netzwerkdiagramme?'),
(394, 7, 557, 'ISO/IEC 27001:2022', 'Anhang A', 'A.5.1', 'Richtlinien zur Informationssicherheit', 'offen', NULL, NULL, NULL, 557, 29, '2026-10-14 10:03:15', NULL, NULL, NULL),
(395, 7, 558, 'ISO/IEC 27001:2022', 'Anhang A', 'A.5.2', 'Überprüfung der Sicherheitsvorgaben', 'offen', NULL, NULL, NULL, 558, 29, '2026-10-14 10:03:15', NULL, NULL, NULL),
