(4, 40, '1. Angaben zum Unternehmen', '1. Company details', 'Name, Funktion und Kontaktdaten der/des Verantwortlichen für Informationssicherheit', 'Name, role and contact details of the person responsible for information security', 'ISO/IEC 27001:2022 5.3', 'text', 1, 1),
(5, 50, '1. Angaben zum Unternehmen', '1. Company details', 'In welchen Ländern werden Daten unseres Unternehmens verarbeitet oder gespeichert?', 'In which countries is our company data processed or stored?', 'DSGVO Art. 44 ff.', 'text', 0, 1),
(6, 60, '2. Informationssicherheits-Managementsystem', '2. Information security management system', 'Ist ein dokumentiertes Informationssicherheits-Managementsystem (ISMS) eingeführt?', 'Has a documented information security management system (ISMS) been established?', 'ISO/IEC 27001:2022 Kap. 4–10; NIS2 Art. 21(2)(a)', 'ja_nein', 1, 1),
(7, 70, '2. Informationssicherheits-Managementsystem', '2. Information security management system', 'Besteht eine gültige Zertifizierung nach ISO/IEC 27001?', 'Do you hold a valid ISO/IEC 27001 certification?', 'ISO/IEC 27001:2022', 'ja_nein', 1, 1),
(8, 80, '2. Informationssicherheits-Managementsystem', '2. Information security management system', 'Falls zertifiziert: Zertifikatsnummer, Zertifizierungsstelle und Gültigkeit bis', 'If certified: certificate number, certification body and validity', 'ISO/IEC 27001:2022', 'text', 0, 1),
(9, 90, '2. Informationssicherheits-Managementsystem', '2. Information security management system', 'Bestehen weitere Zertifizierungen oder Testate (z. B. TISAX, SOC 2 Typ II, BSI IT-Grundschutz, ISO 22301)?', 'Do you hold further certifications or attestations (e.g. TISAX, SOC 2 Type II, BSI IT-Grundschutz, ISO 22301)?', '', 'text', 0, 1),
(10, 100, '2. Informationssicherheits-Managementsystem', '2. Information security management system', 'Gibt es eine von der Leitung verabschiedete Informationssicherheitsleitlinie?', 'Is there an information security policy approved by top management?', 'ISO/IEC 27001:2022 5.2, A.5.1; NIS2 Art. 21(2)(a)', 'ja_nein', 0, 1),
(11, 110, '2. Informationssicherheits-Managementsystem', '2. Information security management system', 'Ist die Geschäftsleitung nachweislich in die Steuerung der Informationssicherheit eingebunden (Rollen, Ressourcen, Schulung)?', 'Is top management demonstrably involved in steering information security (roles, resources, training)?', 'NIS2 Art. 20', 'ja_nein', 0, 1),
(12, 120, '2. Informationssicherheits-Managementsystem', '2. Information security management system', 'Wann fand das letzte interne Audit bzw. die letzte Managementbewertung statt?', 'When did the last internal audit or management review take place?', 'ISO/IEC 27001:2022 9.2, 9.3', 'datum', 0, 1),
(13, 130, '3. Risikomanagement', '3. Risk management', 'Wird ein dokumentiertes Risikomanagement für Informationssicherheit betrieben?', 'Do you operate a documented information security risk management process?', 'ISO/IEC 27001:2022 6.1; NIS2 Art. 21(2)(a)', 'ja_nein', 0, 1),
(14, 140, '3. Risikomanagement', '3. Risk management', 'Werden Risiken mindestens jährlich neu bewertet und die Maßnahmen nachverfolgt?', 'Are risks reassessed at least annually and the measures tracked?', 'ISO/IEC 27001:2022 8.2, 8.3', 'ja_nein', 0, 1),
(15, 150, '4. Zugriffssteuerung und Identitäten', '4. Access control and identities', 'Existiert eine dokumentierte Zugriffssteuerungsrichtlinie nach dem Need-to-know-Prinzip?', 'Is there a documented access control policy following the need-to-know principle?', 'ISO/IEC 27001:2022 A.5.15', 'ja_nein', 0, 1),
(16, 160, '4. Zugriffssteuerung und Identitäten', '4. Access control and identities', 'Werden privilegierte Zugänge gesondert vergeben, dokumentiert und regelmäßig überprüft?', 'Are privileged access rights granted separately, documented and reviewed regularly?', 'ISO/IEC 27001:2022 A.8.2', 'ja_nein', 0, 1),
(17, 170, '4. Zugriffssteuerung und Identitäten', '4. Access control and identities', 'Wird Multi-Faktor-Authentifizierung für Fernzugriffe und administrative Zugänge eingesetzt?', 'Is multi-factor authentication used for remote and administrative access?', 'ISO/IEC 27001:2022 A.8.5; NIS2 Art. 21(2)(j)', 'ja_nein', 0, 1),
(18, 180, '4. Zugriffssteuerung und Identitäten', '4. Access control and identities', 'Werden Zugangsberechtigungen beim Ausscheiden von Mitarbeitenden unverzüglich entzogen?', 'Are access rights revoked immediately when staff leave the organisation?', 'ISO/IEC 27001:2022 A.5.11, A.6.5', 'ja_nein', 0, 1),
(19, 190, '5. Kryptographie und Datenschutz', '5. Cryptography and data protection', 'Werden unsere Daten bei der Übertragung verschlüsselt (mindestens TLS 1.2)?', 'Is our data encrypted in transit (TLS 1.2 or higher)?', 'ISO/IEC 27001:2022 A.8.24; NIS2 Art. 21(2)(h)', 'ja_nein', 0, 1),
(20, 200, '5. Kryptographie und Datenschutz', '5. Cryptography and data protection', 'Werden unsere Daten bei der Speicherung verschlüsselt?', 'Is our data encrypted at rest?', 'ISO/IEC 27001:2022 A.8.24; NIS2 Art. 21(2)(h)', 'ja_nein', 0, 1),
(21, 210, '5. Kryptographie und Datenschutz', '5. Cryptography and data protection', 'Besteht eine Richtlinie zum Einsatz kryptographischer Verfahren einschließlich Schlüsselmanagement?', 'Is there a policy on the use of cryptography including key management?', 'ISO/IEC 27001:2022 A.8.24', 'ja_nein', 0, 1),
(22, 220, '5. Kryptographie und Datenschutz', '5. Cryptography and data protection', 'Werden im Rahmen der Leistung personenbezogene Daten verarbeitet, und liegt ein Auftragsverarbeitungsvertrag vor?', 'Is personal data processed as part of the service, and is a data processing agreement in place?', 'DSGVO Art. 28', 'ja_nein', 0, 1),
(23, 230, '5. Kryptographie und Datenschutz', '5. Cryptography and data protection', 'Wie werden Datenträger und Dokumente nach Ablauf der Aufbewahrungsfrist sicher gelöscht oder vernichtet?', 'How are media and documents securely erased or destroyed at the end of the retention period?', 'ISO/IEC 27001:2022 A.7.14, A.8.10', 'langtext', 0, 1),
(24, 240, '6. Physische Sicherheit', '6. Physical security', 'Sind Rechenzentren und Büroräume durch Zutrittskontrollen geschützt?', 'Are data centres and office premises protected by physical access controls?', 'ISO/IEC 27001:2022 A.7.1–A.7.4', 'ja_nein', 0, 1),
(25, 250, '6. Physische Sicherheit', '6. Physical security', 'An welchen Standorten (Ort und Land) befinden sich die Rechenzentren, in denen unsere Daten liegen?', 'At which locations (city and country) are the data centres holding our data?', 'ISO/IEC 27001:2022 A.7.5', 'text', 0, 1),
(26, 260, '7. Betrieb, Verfügbarkeit und Notfallmanagement', '7. Operations, availability and continuity', 'Werden Datensicherungen regelmäßig erstellt, geschützt aufbewahrt und die Wiederherstellung getestet?', 'Are backups created regularly, stored securely and restore tests performed?', 'ISO/IEC 27001:2022 A.8.13; NIS2 Art. 21(2)(c)', 'ja_nein', 0, 1),
(27, 270, '7. Betrieb, Verfügbarkeit und Notfallmanagement', '7. Operations, availability and continuity', 'Existiert ein getestetes Notfall- und Wiederanlaufkonzept für die für uns erbrachten Leistungen?', 'Is there a tested business continuity and disaster recovery plan for the services provided to us?', 'ISO/IEC 27001:2022 A.5.29, A.5.30; NIS2 Art. 21(2)(c)', 'ja_nein', 0, 1),
(28, 280, '7. Betrieb, Verfügbarkeit und Notfallmanagement', '7. Operations, availability and continuity', 'Welche Wiederanlaufzeit (RTO) und welcher maximal tolerierbare Datenverlust (RPO) werden zugesichert?', 'Which recovery time objective (RTO) and recovery point objective (RPO) do you commit to?', 'ISO/IEC 27001:2022 A.5.30', 'text', 0, 1),
(29, 290, '7. Betrieb, Verfügbarkeit und Notfallmanagement', '7. Operations, availability and continuity', 'Werden Systeme protokolliert und die Protokolle zentral ausgewertet (Monitoring/SIEM)?', 'Are systems logged and the logs centrally evaluated (monitoring/SIEM)?', 'ISO/IEC 27001:2022 A.8.15, A.8.16', 'ja_nein', 0, 1),
(30, 300, '7. Betrieb, Verfügbarkeit und Notfallmanagement', '7. Operations, availability and continuity', 'Besteht auf allen relevanten Systemen ein Schutz gegen Schadsoftware?', 'Is protection against malware in place on all relevant systems?', 'ISO/IEC 27001:2022 A.8.7', 'ja_nein', 0, 1),
(31, 310, '8. Schwachstellen- und Änderungsmanagement', '8. Vulnerability and change management', 'Werden Schwachstellen systematisch erfasst und innerhalb definierter Fristen behoben (Patch-Management)?', 'Are vulnerabilities recorded systematically and remediated within defined deadlines (patch management)?', 'ISO/IEC 27001:2022 A.8.8; NIS2 Art. 21(2)(e)', 'ja_nein', 0, 1),
(32, 320, '8. Schwachstellen- und Änderungsmanagement', '8. Vulnerability and change management', 'Werden regelmäßig Schwachstellenscans oder Penetrationstests durchgeführt?', 'Are vulnerability scans or penetration tests carried out regularly?', 'ISO/IEC 27001:2022 A.8.8', 'ja_nein', 0, 1),
(33, 330, '8. Schwachstellen- und Änderungsmanagement', '8. Vulnerability and change management', 'Besteht ein dokumentiertes Änderungsmanagement für produktive Systeme?', 'Is there a documented change management process for production systems?', 'ISO/IEC 27001:2022 A.8.32', 'ja_nein', 0, 1),
(34, 340, '8. Schwachstellen- und Änderungsmanagement', '8. Vulnerability and change management', 'Werden bei Eigenentwicklungen Grundsätze der sicheren Entwicklung angewandt?', 'Are secure development principles applied to in-house software development?', 'ISO/IEC 27001:2022 A.8.25–A.8.28; NIS2 Art. 21(2)(e)', 'ja_nein', 0, 1),
(35, 350, '9. Sicherheitsvorfälle und Meldepflichten', '9. Security incidents and reporting duties', 'Existiert ein dokumentierter Prozess zur Behandlung von Sicherheitsvorfällen mit benannten Verantwortlichen?', 'Is there a documented incident handling process with designated responsibilities?', 'ISO/IEC 27001:2022 A.5.24–A.5.26; NIS2 Art. 21(2)(b)', 'ja_nein', 1, 1),
(36, 360, '9. Sicherheitsvorfälle und Meldepflichten', '9. Security incidents and reporting duties', 'Sagen Sie zu, uns Sicherheitsvorfälle mit Auswirkung auf unsere Daten oder Leistungen unverzüglich, spätestens innerhalb von 24 Stunden, zu melden?', 'Do you commit to reporting security incidents affecting our data or services without undue delay, at the latest within 24 hours?', 'NIS2 Art. 23; ISO/IEC 27001:2022 A.5.5', 'ja_nein', 1, 1),
(37, 370, '9. Sicherheitsvorfälle und Meldepflichten', '9. Security incidents and reporting duties', 'Über welche Adresse und Rufnummer können wir Sicherheitsvorfälle rund um die Uhr melden?', 'Which address and phone number can we use to report security incidents around the clock?', 'ISO/IEC 27001:2022 A.5.24', 'text', 1, 1),
(38, 380, '9. Sicherheitsvorfälle und Meldepflichten', '9. Security incidents and reporting duties', 'Gab es in den letzten 24 Monaten meldepflichtige Sicherheitsvorfälle mit Auswirkung auf Kundendaten?', 'Were there any reportable security incidents affecting customer data in the last 24 months?', 'NIS2 Art. 23', 'ja_nein', 0, 1),
(39, 390, '9. Sicherheitsvorfälle und Meldepflichten', '9. Security incidents and reporting duties', 'Falls ja: Bitte beschreiben Sie den Vorfall und die ergriffenen Maßnahmen.', 'If yes: please describe the incident and the measures taken.', '', 'langtext', 0, 1),
(40, 400, '10. Lieferkette und Subunternehmer', '10. Supply chain and subcontractors', 'Setzen Sie zur Erbringung der Leistung Subunternehmer oder Cloud-Dienste ein?', 'Do you use subcontractors or cloud services to deliver the service?', 'ISO/IEC 27001:2022 A.5.21; NIS2 Art. 21(2)(d)', 'ja_nein', 0, 1),
(41, 410, '10. Lieferkette und Subunternehmer', '10. Supply chain and subcontractors', 'Falls ja: Welche Subunternehmer bzw. Dienste sind das, und in welchen Ländern sind sie tätig?', 'If yes: which subcontractors or services are these, and in which countries do they operate?', 'ISO/IEC 27001:2022 A.5.21', 'langtext', 0, 1),
(42, 420, '10. Lieferkette und Subunternehmer', '10. Supply chain and subcontractors', 'Werden Ihre Subunternehmer vertraglich auf gleichwertige Sicherheitsanforderungen verpflichtet und regelmäßig überprüft?', 'Are your subcontractors contractually bound to equivalent security requirements and reviewed regularly?', 'ISO/IEC 27001:2022 A.5.19–A.5.22; NIS2 Art. 21(2)(d)', 'ja_nein', 0, 1),
(43, 430, '11. Personal und Sensibilisierung', '11. Personnel and awareness', 'Werden Mitarbeitende vor Aufnahme der Tätigkeit überprüft, soweit rechtlich zulässig?', 'Are staff screened before employment, as far as legally permitted?', 'ISO/IEC 27001:2022 A.6.1', 'ja_nein', 0, 1),
(44, 440, '11. Personal und Sensibilisierung', '11. Personnel and awareness', 'Sind alle Mitarbeitenden zur Vertraulichkeit verpflichtet (Geheimhaltungsvereinbarung)?', 'Are all staff bound by confidentiality (non-disclosure agreement)?', 'ISO/IEC 27001:2022 A.6.6', 'ja_nein', 0, 1),
(45, 450, '11. Personal und Sensibilisierung', '11. Personnel and awareness', 'Finden mindestens jährlich Schulungen zur Informationssicherheit statt?', 'Are information security awareness trainings held at least annually?', 'ISO/IEC 27001:2022 A.6.3; NIS2 Art. 21(2)(g)', 'ja_nein', 0, 1),
(46, 460, '12. Nachweise und Abschluss', '12. Evidence and completion', 'Gewähren Sie uns oder einem von uns beauftragten Dritten auf Anfrage Audit- und Nachweisrechte?', 'Do you grant us or a third party appointed by us audit and evidence rights on request?', 'ISO/IEC 27001:2022 A.5.22', 'ja_nein', 0, 1),
(47, 470, '12. Nachweise und Abschluss', '12. Evidence and completion', 'Welche Nachweise können Sie zu diesem Fragebogen vorlegen (Zertifikate, Auditberichte, Erklärung zur Anwendbarkeit)?', 'Which evidence can you provide alongside this questionnaire (certificates, audit reports, statement of applicability)?', '', 'langtext', 0, 1),
(48, 480, '12. Nachweise und Abschluss', '12. Evidence and completion', 'Ergänzende Anmerkungen', 'Additional remarks', '', 'langtext', 0, 1),
(49, 490, '12. Nachweise und Abschluss', '12. Evidence and completion', 'Name und Funktion der ausfüllenden Person', 'Name and role of the person completing this questionnaire', '', 'text', 1, 1);

